export interface RawLogEntry {
  [key: string]: string | number | undefined;
}

export interface ProcessedLogEntry {
  id: string;
  timestamp: string;
  originalTimestamp: string;
  method: string;
  path: string; // Normalized path
  fullRequest: string;
  status: number;
  latency: number; // request_time
  upstreamLatency: number; // upstream_response_time
  userAgent: string;
  remoteIp: string;
  referer: string;
  isError: boolean;
  bodyBytes: number;
}

export interface AggregatedStats {
  totalRequests: number;
  avgLatency: number;
  p95Latency: number;
  errorRate: number;
  totalBytes: number;
  requestsOverTime: { time: string; count: number; errorCount: number; avgLatency: number }[];
  statusDistribution: { name: string; value: number; fill: string }[];
  topEndpoints: { path: string; count: number; avgLatency: number; errorRate: number }[];
  methodDistribution: { name: string; value: number }[];
}

export enum FilterTimeRange {
  ALL = 'ALL',
  LAST_HOUR = 'LAST_HOUR',
  LAST_24_HOURS = 'LAST_24_HOURS',
}

import { ProcessedLogEntry, AggregatedStats } from './types';

// Helper to calculate percentile
const calculatePercentile = (data: number[], percentile: number) => {
  if (data.length === 0) return 0;
  const sorted = [...data].sort((a, b) => a - b);
  const index = Math.ceil((percentile / 100) * sorted.length) - 1;
  return sorted[index];
};

// URL Normalization Logic
const normalizePath = (requestStr: string): { method: string; path: string } => {
  if (!requestStr || requestStr === '-') return { method: 'UNKNOWN', path: 'UNKNOWN' };

  // Typical format: "GET /path/to/resource?query=1 HTTP/1.1"
  const parts = requestStr.split(' ');
  const method = parts.length > 0 ? parts[0] : 'UNKNOWN';
  let rawPath = parts.length > 1 ? parts[1] : '';

  // 1. Remove Query Parameters
  let path = rawPath.split('?')[0];

  // 2. Normalize IDs (Heuristic: segments that are numeric or long hex strings)
  // Replace pure numbers with :id
  path = path.replace(/\/\d+(\/|$)/g, '/:id$1');

  // Replace UUID-like strings (simple heuristic)
  path = path.replace(/\/[a-f0-9-]{32,}(\/|$)/g, '/:uuid$1');

  return { method, path };
};

export const parseCSV = (csvText: string): ProcessedLogEntry[] => {
  const lines = csvText.split(/\r?\n/).filter(line => line.trim() !== '');
  if (lines.length < 2) return [];

  // Detect delimiter (Tab or Comma)
  const firstLine = lines[0];
  const separator = firstLine.includes('\t') ? '\t' : ',';

  const headers = firstLine.split(separator).map(h => h.trim().replace(/^'|'$/g, '')); // Remove surrounding quotes if any

  // Find Indices of critical columns
  const findIdx = (keyPart: string) => headers.findIndex(h => h.includes(keyPart));

  const idxStatus = findIdx('jsonPayload.status');
  const idxRequest = findIdx('jsonPayload.request');
  const idxReqTime = findIdx('jsonPayload.request_time');
  const idxUpstreamTime = findIdx('jsonPayload.upstream_response_time');
  const idxUserAgent = findIdx('jsonPayload.http_user_agent');
  const idxRemoteAddr = findIdx('jsonPayload.remote_addr');
  const idxTimeLocal = findIdx('jsonPayload.time_local');
  const idxBodyBytes = findIdx('jsonPayload.body_bytes_sent');
  const idxReferer = findIdx('jsonPayload.http_referer');

  const processed: ProcessedLogEntry[] = [];

  for (let i = 1; i < lines.length; i++) {
    // Handle potential quoted strings in CSV, simpler split for TSV
    const cells = lines[i].split(separator).map(c => c.trim().replace(/^"|"$/g, ''));

    // Skip malformed lines
    if (cells.length < headers.length * 0.5) continue; 

    const requestStr = cells[idxRequest] || '-';
    const { method, path } = normalizePath(requestStr);
    const status = parseInt(cells[idxStatus] || '0', 10);
    const latency = parseFloat(cells[idxReqTime] || '0');

    // Parse timestamp (16/Jan/2026:10:59:49 +0000)
    // We convert this to ISO for easier sorting/filtering
    let isoTime = new Date().toISOString(); 
    const rawTime = cells[idxTimeLocal];
    if (rawTime) {
        // Simple manual parse for Nginx default format: DD/Mon/YYYY:HH:MM:SS Z
        const parts = rawTime.split(/:| /); // Split by colon or space
        if (parts.length >= 4) {
             // This is a rough estimation for the visualization as exact parsing depends on locale
             // For the demo, we rely on the string or assume the user uploads recent data.
             // Let's try to make a valid date object.
             // 16/Jan/2026:10:59:49 +0000 -> 16 Jan 2026 10:59:49 GMT
             const dateStr = rawTime.replace(':', ' '); 
             const d = new Date(dateStr);
             if (!isNaN(d.getTime())) {
                 isoTime = d.toISOString();
             }
        }
    }

    processed.push({
      id: `log-${i}`,
      timestamp: isoTime,
      originalTimestamp: rawTime || '',
      method,
      path,
      fullRequest: requestStr,
      status: isNaN(status) ? 0 : status,
      latency: isNaN(latency) ? 0 : latency,
      upstreamLatency: parseFloat(cells[idxUpstreamTime] || '0'),
      userAgent: cells[idxUserAgent] || '-',
      remoteIp: cells[idxRemoteAddr] || '-',
      referer: cells[idxReferer] || '-',
      isError: status >= 400,
      bodyBytes: parseInt(cells[idxBodyBytes] || '0', 10),
    });
  }

  return processed;
};

export const aggregateStats = (logs: ProcessedLogEntry[]): AggregatedStats => {
  const totalRequests = logs.length;
  if (totalRequests === 0) {
    return {
      totalRequests: 0,
      avgLatency: 0,
      p95Latency: 0,
      errorRate: 0,
      totalBytes: 0,
      requestsOverTime: [],
      statusDistribution: [],
      topEndpoints: [],
      methodDistribution: [],
    };
  }

  const latencies = logs.map(l => l.latency);
  const totalLatency = latencies.reduce((a, b) => a + b, 0);
  const totalBytes = logs.reduce((a, b) => a + (isNaN(b.bodyBytes) ? 0 : b.bodyBytes), 0);
  const errorCount = logs.filter(l => l.isError).length;

  // Status Distribution
  const statusCounts: Record<string, number> = {};
  logs.forEach(l => {
    const cat = Math.floor(l.status / 100) + 'xx';
    statusCounts[cat] = (statusCounts[cat] || 0) + 1;
  });

  const statusColors: Record<string, string> = {
    '2xx': '#10b981', // Emerald 500
    '3xx': '#3b82f6', // Blue 500
    '4xx': '#f59e0b', // Amber 500
    '5xx': '#ef4444', // Red 500
    '0xx': '#94a3b8', // Slate 400
  };

  const statusDistribution = Object.entries(statusCounts).map(([name, value]) => ({
    name,
    value,
    fill: statusColors[name] || '#64748b',
  }));

  // Endpoint Aggregation
  const endpointMap: Record<string, { count: number; totalLat: number; errors: number }> = {};
  logs.forEach(l => {
    const key = `${l.method} ${l.path}`;
    if (!endpointMap[key]) endpointMap[key] = { count: 0, totalLat: 0, errors: 0 };
    endpointMap[key].count++;
    endpointMap[key].totalLat += l.latency;
    if (l.isError) endpointMap[key].errors++;
  });

  const topEndpoints = Object.entries(endpointMap)
    .map(([path, data]) => ({
      path,
      count: data.count,
      avgLatency: data.totalLat / data.count,
      errorRate: (data.errors / data.count) * 100,
    }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 10); // Top 10

  // Time Series (Bucketing by Minute)
  const timeMap: Record<string, { count: number; errors: number; totalLat: number }> = {};
  logs.forEach(l => {
    // Bucket by minute: YYYY-MM-DDTHH:MM
    const bucket = l.timestamp.substring(0, 16).replace('T', ' ');
    if (!timeMap[bucket]) timeMap[bucket] = { count: 0, errors: 0, totalLat: 0 };
    timeMap[bucket].count++;
    timeMap[bucket].totalLat += l.latency;
    if (l.isError) timeMap[bucket].errors++;
  });

  const requestsOverTime = Object.entries(timeMap)
    .map(([time, data]) => ({
      time,
      count: data.count,
      errorCount: data.errors,
      avgLatency: data.totalLat / data.count,
    }))
    .sort((a, b) => new Date(a.time).getTime() - new Date(b.time).getTime());

  // Method Distribution
  const methodCounts: Record<string, number> = {};
  logs.forEach(l => {
    methodCounts[l.method] = (methodCounts[l.method] || 0) + 1;
  });
  const methodDistribution = Object.entries(methodCounts).map(([name, value]) => ({ name, value }));

  return {
    totalRequests,
    avgLatency: totalLatency / totalRequests,
    p95Latency: calculatePercentile(latencies, 95),
    errorRate: (errorCount / totalRequests) * 100,
    totalBytes,
    requestsOverTime,
    statusDistribution,
    topEndpoints,
    methodDistribution,
  };
};

import React, { useRef, useState } from 'react';
import { UploadCloud, FileText, AlertCircle } from 'lucide-react';

interface FileUploadProps {
  onDataLoaded: (content: string) => void;
}

const FileUpload: React.FC<FileUploadProps> = ({ onDataLoaded }) => {
  const [isDragging, setIsDragging] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFile = (file: File) => {
    setError(null);
    if (file.type !== 'text/csv' && !file.name.endsWith('.csv') && !file.name.endsWith('.tsv')) {
      setError('Please upload a valid CSV or TSV file.');
      return;
    }

    setIsLoading(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (text) {
        // Simulate a small delay for UI effect
        setTimeout(() => {
            onDataLoaded(text);
            setIsLoading(false);
        }, 800);
      }
    };
    reader.onerror = () => {
      setError('Failed to read file.');
      setIsLoading(false);
    };
    reader.readAsText(file);
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleFile(e.dataTransfer.files[0]);
    }
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const onDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-[60vh] p-4 animate-fade-in">
      <div className="max-w-xl w-full text-center space-y-6">
        <h1 className="text-4xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-emerald-400">
          LogPulse Analytics
        </h1>
        <p className="text-slate-400 text-lg">
          Upload your raw access logs to generate instant insights, normalized metrics, and innovative visualizations.
        </p>

        <div
          className={`
            relative group cursor-pointer
            border-2 border-dashed rounded-2xl p-12 transition-all duration-300
            flex flex-col items-center justify-center gap-4
            ${isDragging 
              ? 'border-blue-500 bg-blue-500/10 scale-102' 
              : 'border-slate-700 bg-slate-800/50 hover:border-slate-500 hover:bg-slate-800'}
          `}
          onDrop={onDrop}
          onDragOver={onDragOver}
          onDragLeave={onDragLeave}
          onClick={() => fileInputRef.current?.click()}
        >
          <input
            type="file"
            ref={fileInputRef}
            onChange={(e) => e.target.files?.[0] && handleFile(e.target.files[0])}
            className="hidden"
            accept=".csv,.tsv,.txt"
          />

          {isLoading ? (
            <div className="flex flex-col items-center gap-4 animate-pulse">
               <div className="w-16 h-16 rounded-full border-4 border-blue-500 border-t-transparent animate-spin"></div>
               <p className="text-blue-400 font-medium">Processing logs...</p>
            </div>
          ) : (
            <>
              <div className="w-20 h-20 rounded-full bg-slate-900 flex items-center justify-center shadow-lg group-hover:scale-110 transition-transform duration-300">
                <UploadCloud className="w-10 h-10 text-blue-400" />
              </div>
              <div className="space-y-2">
                <p className="text-xl font-semibold text-slate-200">
                  Click to upload or drag and drop
                </p>
                <p className="text-sm text-slate-500">
                  Supports CSV, TSV (GCP Logging format recommended)
                </p>
              </div>
            </>
          )}
        </div>

        {error && (
          <div className="flex items-center justify-center gap-2 text-red-400 bg-red-400/10 p-3 rounded-lg">
            <AlertCircle size={18} />
            <span>{error}</span>
          </div>
        )}

        <div className="flex justify-center gap-8 mt-8 text-slate-500 text-sm">
            <div className="flex items-center gap-2">
                <FileText size={16} />
                <span>Local Processing</span>
            </div>
            <div className="flex items-center gap-2">
                <FileText size={16} />
                <span>URL Normalization</span>
            </div>
            <div className="flex items-center gap-2">
                <FileText size={16} />
                <span>Latency Analysis</span>
            </div>
        </div>
      </div>
    </div>
  );
};

export default FileUpload;

import React from 'react';
import { LucideIcon } from 'lucide-react';

