export default StatsCard;

import React from 'react';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  Legend,
  ComposedChart,
  Line
} from 'recharts';
import { AggregatedStats } from '../types';

interface ChartsProps {
  data: AggregatedStats;
}

const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-slate-900 border border-slate-700 p-3 rounded shadow-xl">
        <p className="text-slate-300 text-sm mb-2">{label}</p>
        {payload.map((entry: any, index: number) => (
          <div key={index} className="flex items-center gap-2 text-sm">
            <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }} />
            <span className="text-slate-400 capitalize">{entry.name}:</span>
            <span className="text-slate-200 font-mono">
                {typeof entry.value === 'number' && entry.name.includes('Latency') 
                    ? entry.value.toFixed(2) + 'ms' 
                    : entry.value}
            </span>
          </div>
        ))}
      </div>
    );
  }
  return null;
};

export const TrafficChart: React.FC<ChartsProps> = ({ data }) => {
  return (
    <div className="w-full h-[350px]">
      <ResponsiveContainer width="100%" height="100%">
        <ComposedChart data={data.requestsOverTime}>
          <defs>
            <linearGradient id="colorCount" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3} />
              <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
            </linearGradient>
            <linearGradient id="colorError" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="#ef4444" stopOpacity={0.3} />
              <stop offset="95%" stopColor="#ef4444" stopOpacity={0} />
            </linearGradient>
          </defs>
          <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
          <XAxis 
            dataKey="time" 
            stroke="#94a3b8" 
            tickFormatter={(str) => str.split(' ')[1]} 
            tick={{fontSize: 12}}
            minTickGap={30}
          />
          <YAxis yAxisId="left" stroke="#94a3b8" tick={{fontSize: 12}} />
          <YAxis yAxisId="right" orientation="right" stroke="#10b981" unit="ms" tick={{fontSize: 12}} />
          <Tooltip content={<CustomTooltip />} />
          <Legend />
          <Area
            yAxisId="left"
            type="monotone"
            dataKey="count"
            name="Requests"
            stroke="#3b82f6"
            fillOpacity={1}
            fill="url(#colorCount)"
            strokeWidth={2}
          />
           <Area
            yAxisId="left"
            type="monotone"
            dataKey="errorCount"
            name="Errors"
            stroke="#ef4444"
            fillOpacity={1}
            fill="url(#colorError)"
            strokeWidth={2}
          />
          <Line
            yAxisId="right"
            type="monotone"
            dataKey="avgLatency"
            name="Avg Latency"
            stroke="#10b981"
            dot={false}
            strokeWidth={2}
          />
        </ComposedChart>
      </ResponsiveContainer>
    </div>
  );
};

export const StatusDistribution: React.FC<ChartsProps> = ({ data }) => {
  return (
    <div className="w-full h-[250px]">
      <ResponsiveContainer width="100%" height="100%">
        <PieChart>
          <Pie
            data={data.statusDistribution}
            cx="50%"
            cy="50%"
            innerRadius={60}
