            type="category" 
            dataKey="shortPath" 
            stroke="#94a3b8" 
            width={150} 
            tick={{fontSize: 11}}
          />
          <Tooltip content={<CustomTooltip />} cursor={{fill: '#1e293b'}} />
          <Legend />
          <Bar dataKey="count" name="Volume" fill="#8b5cf6" radius={[0, 4, 4, 0]} barSize={20} />
          <Bar dataKey="avgLatency" name="Latency (ms)" fill="#f59e0b" radius={[0, 4, 4, 0]} barSize={20} />
        </BarChart>
