};

import React, { useMemo, useState } from 'react';
import { ProcessedLogEntry } from '../types';
import { aggregateStats } from '../utils';
import StatsCard from './StatsCard';
import { TrafficChart, StatusDistribution, TopEndpointsChart } from './Charts';
import { Activity, AlertTriangle, Clock, Database, Filter, ArrowLeft, Search } from 'lucide-react';

interface DashboardProps {
  logs: ProcessedLogEntry[];
  onReset: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ logs, onReset }) => {
  const [filterText, setFilterText] = useState('');
  const [filterStatus, setFilterStatus] = useState<string>('all');

  // Filter logs based on user input
  const filteredLogs = useMemo(() => {
    return logs.filter(log => {
      const matchesText = 
        log.path.toLowerCase().includes(filterText.toLowerCase()) || 
        log.method.toLowerCase().includes(filterText.toLowerCase());

      const matchesStatus = filterStatus === 'all' 
        ? true 
        : filterStatus === 'error' 
          ? log.isError 
          : true;

      return matchesText && matchesStatus;
    });
  }, [logs, filterText, filterStatus]);

  const stats = useMemo(() => aggregateStats(filteredLogs), [filteredLogs]);

  // Format bytes to readable string
  const formatBytes = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-200 pb-20">
      {/* Navbar */}
      <nav className="border-b border-slate-800 bg-slate-900/80 backdrop-blur sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
            <div className="flex items-center gap-4">
                <button 
                    onClick={onReset}
                    className="p-2 hover:bg-slate-800 rounded-lg transition-colors text-slate-400 hover:text-white"
                >
                    <ArrowLeft size={20} />
                </button>
                <div className="flex flex-col">
                    <span className="font-bold text-lg bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-emerald-400">
                    LogPulse
                    </span>
                    <span className="text-xs text-slate-500">
                        {logs.length.toLocaleString()} total events
                    </span>
                </div>
            </div>

            <div className="flex items-center gap-4">
                <div className="relative group">
                    <Search className="absolute left-3 top-2.5 text-slate-500 group-focus-within:text-blue-400 w-4 h-4" />
                    <input 
                        type="text" 
                        placeholder="Search paths or methods..." 
                        value={filterText}
                        onChange={(e) => setFilterText(e.target.value)}
                        className="bg-slate-800 border border-slate-700 text-sm rounded-full pl-10 pr-4 py-2 w-64 focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition-all"
                    />
                </div>
                <div className="flex items-center bg-slate-800 rounded-lg p-1 border border-slate-700">
                    <button 
                        onClick={() => setFilterStatus('all')}
                        className={`px-3 py-1 text-sm rounded-md transition-all ${filterStatus === 'all' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-400 hover:text-slate-200'}`}
                    >
                        All
                    </button>
                    <button 
                        onClick={() => setFilterStatus('error')}
                        className={`px-3 py-1 text-sm rounded-md transition-all flex items-center gap-2 ${filterStatus === 'error' ? 'bg-red-500/20 text-red-400 shadow-sm' : 'text-slate-400 hover:text-red-400'}`}
                    >
                        Errors
                    </button>
                </div>
            </div>
        </div>
