import { ProcessedLogEntry, AggregatedStats } from './types';

// Helper to calculate percentile
const calculatePercentile = (data: number[], percentile: number) => {
  if (data.length === 0) return 0;
  const sorted = [...data].sort((a, b) => a - b);
  const index = Math.ceil((percentile / 100) * sorted.length) - 1;
  return sorted[index];
};

// URL Normalization Logic
const normalizePath = (requestStr: string): { method: string; path: string } => {
  if (!requestStr || requestStr === '-') return { method: 'UNKNOWN', path: 'UNKNOWN' };

  // Typical format: "GET /path/to/resource?query=1 HTTP/1.1"
  const parts = requestStr.split(' ');
  const method = parts.length > 0 ? parts[0] : 'UNKNOWN';
  let rawPath = parts.length > 1 ? parts[1] : '';

  // 1. Remove Query Parameters
  let path = rawPath.split('?')[0];

  // 2. Normalize IDs (Heuristic: segments that are numeric or long hex strings)
  // Replace pure numbers with :id
  path = path.replace(/\/\d+(\/|$)/g, '/:id$1');

  // Replace UUID-like strings (simple heuristic)
  path = path.replace(/\/[a-f0-9-]{32,}(\/|$)/g, '/:uuid$1');

  return { method, path };
};

const getField = (obj: any, keys: string[]): any => {
    for (const key of keys) {
        // Direct access
        if (obj[key] !== undefined) return obj[key];

        // Nested access (e.g., jsonPayload.status)
        const parts = key.split('.');
        if (parts.length > 1) {
            let val = obj;
            let found = true;
            for(const p of parts) {
                if(val && typeof val === 'object' && p in val) {
                    val = val[p];
                } else {
                    found = false;
                    break;
                }
            }
            if (found && val !== undefined) return val;
        }
    }
    return undefined;
};

const parseDate = (rawTime: string): string => {
    if (!rawTime) return new Date().toISOString();

    // Nginx default format: DD/Mon/YYYY:HH:MM:SS Z
    // e.g., 16/Jan/2026:10:59:49 +0000
    const parts = rawTime.split(/:| /); 
    if (parts.length >= 4) {
         const dateStr = rawTime.replace(':', ' '); 
         const d = new Date(dateStr);
         if (!isNaN(d.getTime())) {
             return d.toISOString();
         }
    }
    // Fallback if Date.parse works directly (ISO strings)
    const d = new Date(rawTime);
    if (!isNaN(d.getTime())) return d.toISOString();

    return new Date().toISOString();
};

const parseJSONLines = (lines: string[]): ProcessedLogEntry[] => {
    return lines.map((line, i) => {
        try {
            if (!line.trim()) return null;
            const json = JSON.parse(line);

            const requestStr = getField(json, ['request', 'jsonPayload.request']) || '-';
            const { method, path } = normalizePath(requestStr);
            const status = parseInt(getField(json, ['status', 'jsonPayload.status']) || '0', 10);
            const latency = parseFloat(getField(json, ['request_time', 'jsonPayload.request_time']) || '0');
            const upstreamLat = parseFloat(getField(json, ['upstream_response_time', 'jsonPayload.upstream_response_time']) || '0');
            const rawTime = getField(json, ['time_local', 'jsonPayload.time_local', 'timestamp']) || '';

            return {
                id: `log-json-${i}`,
                timestamp: parseDate(rawTime),
                originalTimestamp: rawTime,
                method,
                path,
                fullRequest: requestStr,
                status: isNaN(status) ? 0 : status,
                latency: isNaN(latency) ? 0 : latency,
                upstreamLatency: upstreamLat,
                userAgent: getField(json, ['http_user_agent', 'jsonPayload.http_user_agent']) || '-',
                remoteIp: getField(json, ['remote_addr', 'jsonPayload.remote_addr']) || '-',
                referer: getField(json, ['http_referer', 'jsonPayload.http_referer']) || '-',
                isError: status >= 400,
                bodyBytes: parseInt(getField(json, ['body_bytes_sent', 'jsonPayload.body_bytes_sent']) || '0', 10),
            };
        } catch (e) {
            console.warn("Failed to parse JSON line", e);
            return null;
        }
    }).filter(Boolean) as ProcessedLogEntry[];
};

export const parseLogs = (content: string): ProcessedLogEntry[] => {
  const lines = content.split(/\r?\n/).filter(line => line.trim() !== '');
  if (lines.length === 0) return [];

  if (lines[0].trim().startsWith('{')) {
      return parseJSONLines(lines);
  }

  // Fallback to CSV/TSV
  return parseCSV(lines);
};

const parseCSV = (lines: string[]): ProcessedLogEntry[] => {
  if (lines.length < 2) return [];

  // Detect delimiter (Tab or Comma)
  const firstLine = lines[0];
  const separator = firstLine.includes('\t') ? '\t' : ',';

  const headers = firstLine.split(separator).map(h => h.trim().replace(/^'|'$/g, ''));

  const findIdx = (keyParts: string[]) => headers.findIndex(h => keyParts.some(k => h.includes(k)));

  const idxStatus = findIdx(['jsonPayload.status', 'status']);
  const idxRequest = findIdx(['jsonPayload.request', 'request']);
  const idxReqTime = findIdx(['jsonPayload.request_time', 'request_time']);
  const idxUpstreamTime = findIdx(['jsonPayload.upstream_response_time', 'upstream_response_time']);
  const idxUserAgent = findIdx(['jsonPayload.http_user_agent', 'http_user_agent']);
  const idxRemoteAddr = findIdx(['jsonPayload.remote_addr', 'remote_addr']);
  const idxTimeLocal = findIdx(['jsonPayload.time_local', 'time_local']);
  const idxBodyBytes = findIdx(['jsonPayload.body_bytes_sent', 'body_bytes_sent']);
  const idxReferer = findIdx(['jsonPayload.http_referer', 'http_referer']);

  const processed: ProcessedLogEntry[] = [];

  for (let i = 1; i < lines.length; i++) {
    const cells = lines[i].split(separator).map(c => c.trim().replace(/^"|"$/g, ''));
    if (cells.length < headers.length * 0.5) continue; 

    const requestStr = cells[idxRequest] || '-';
    const { method, path } = normalizePath(requestStr);
    const status = parseInt(cells[idxStatus] || '0', 10);
    const latency = parseFloat(cells[idxReqTime] || '0');
    const rawTime = cells[idxTimeLocal];

    processed.push({
      id: `log-${i}`,
      timestamp: parseDate(rawTime),
      originalTimestamp: rawTime || '',
      method,
      path,
      fullRequest: requestStr,
      status: isNaN(status) ? 0 : status,
      latency: isNaN(latency) ? 0 : latency,
      upstreamLatency: parseFloat(cells[idxUpstreamTime] || '0'),
      userAgent: cells[idxUserAgent] || '-',
      remoteIp: cells[idxRemoteAddr] || '-',
      referer: cells[idxReferer] || '-',
      isError: status >= 400,
      bodyBytes: parseInt(cells[idxBodyBytes] || '0', 10),
    });
  }

  return processed;
};

export const aggregateStats = (logs: ProcessedLogEntry[]): AggregatedStats => {
  const totalRequests = logs.length;
  if (totalRequests === 0) {
    return {
      totalRequests: 0,
      avgLatency: 0,
      p95Latency: 0,
      errorRate: 0,
      totalBytes: 0,
      requestsOverTime: [],
      statusDistribution: [],
      topEndpoints: [],
      methodDistribution: [],
    };
  }

  const latencies = logs.map(l => l.latency);
  const totalLatency = latencies.reduce((a, b) => a + b, 0);
  const totalBytes = logs.reduce((a, b) => a + (isNaN(b.bodyBytes) ? 0 : b.bodyBytes), 0);
  const errorCount = logs.filter(l => l.isError).length;

  // Status Distribution
  const statusCounts: Record<string, number> = {};
  logs.forEach(l => {
    const cat = Math.floor(l.status / 100) + 'xx';
    statusCounts[cat] = (statusCounts[cat] || 0) + 1;
  });

  const statusColors: Record<string, string> = {
    '2xx': '#10b981', // Emerald 500
    '3xx': '#3b82f6', // Blue 500
    '4xx': '#f59e0b', // Amber 500
    '5xx': '#ef4444', // Red 500
    '0xx': '#94a3b8', // Slate 400
  };

  const statusDistribution = Object.entries(statusCounts).map(([name, value]) => ({
    name,
    value,
    fill: statusColors[name] || '#64748b',
  }));

  // Endpoint Aggregation
  const endpointMap: Record<string, { count: number; totalLat: number; errors: number }> = {};
  logs.forEach(l => {
    const key = `${l.method} ${l.path}`;
    if (!endpointMap[key]) endpointMap[key] = { count: 0, totalLat: 0, errors: 0 };
    endpointMap[key].count++;
    endpointMap[key].totalLat += l.latency;
    if (l.isError) endpointMap[key].errors++;
  });

  const topEndpoints = Object.entries(endpointMap)
    .map(([path, data]) => ({
      path,
      count: data.count,
      avgLatency: data.totalLat / data.count,
      errorRate: (data.errors / data.count) * 100,
    }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 10); // Top 10

  // Time Series (Bucketing by Minute)
  const timeMap: Record<string, { count: number; errors: number; totalLat: number }> = {};
  logs.forEach(l => {
    // Bucket by minute: YYYY-MM-DDTHH:MM
    const bucket = l.timestamp.substring(0, 16).replace('T', ' ');
    if (!timeMap[bucket]) timeMap[bucket] = { count: 0, errors: 0, totalLat: 0 };
    timeMap[bucket].count++;
    timeMap[bucket].totalLat += l.latency;
    if (l.isError) timeMap[bucket].errors++;
  });

  const requestsOverTime = Object.entries(timeMap)
    .map(([time, data]) => ({
      time,
      count: data.count,
      errorCount: data.errors,
      avgLatency: data.totalLat / data.count,
    }))
    .sort((a, b) => new Date(a.time).getTime() - new Date(b.time).getTime());

  // Method Distribution
  const methodCounts: Record<string, number> = {};
  logs.forEach(l => {
    methodCounts[l.method] = (methodCounts[l.method] || 0) + 1;
  });
  const methodDistribution = Object.entries(methodCounts).map(([name, value]) => ({ name, value }));

  return {
    totalRequests,
    avgLatency: totalLatency / totalRequests,
    p95Latency: calculatePercentile(latencies, 95),
    errorRate: (errorCount / totalRequests) * 100,
    totalBytes,
    requestsOverTime,
    statusDistribution,
    topEndpoints,
    methodDistribution,
  };
};

import React, { useState, useCallback } from 'react';
import FileUpload from './components/FileUpload';
import Dashboard from './components/Dashboard';
import { parseLogs } from './utils';
import { ProcessedLogEntry } from './types';

function App() {
  const [logs, setLogs] = useState<ProcessedLogEntry[] | null>(null);

  const handleDataLoaded = useCallback((content: string) => {
    const parsedLogs = parseLogs(content);
    setLogs(parsedLogs);
  }, []);

  const handleReset = () => {
    setLogs(null);
  };

  return (
    <div className="min-h-screen bg-[#0f172a]">
      {logs ? (
        <Dashboard logs={logs} onReset={handleReset} />
      ) : (
        <FileUpload onDataLoaded={handleDataLoaded} />
      )}
    </div>
  );
}

