export interface RawLogEntry {
  [key: string]: string | number | undefined;
}

export type LogSeverity = 'INFO' | 'WARN' | 'ERROR' | 'CRITICAL';

export interface ProcessedLogEntry {
  id: string;
  timestamp: string;
  originalTimestamp: string;
  method: string;
  path: string; // Normalized path
  fullRequest: string;
  status: number;
  latency: number; // request_time
  upstreamLatency: number; // upstream_response_time
  userAgent: string;
  remoteIp: string;
  referer: string;
  isError: boolean;
  severity: LogSeverity;
  bodyBytes: number;
  clusterId?: string; // For pattern grouping
  rawLine: string; // Original raw line for display
  metadata: Record<string, any>; // Flexible bag for extra fields
}

export interface LogCluster {
  id: string;
  template: string; // The pattern with variables replaced
  sample: string;
  count: number;
  errorCount: number;
  avgLatency: number;
