  const generateMockResponse = (query: string): string => {
      const q = query.toLowerCase();
      if (q.includes('error')) {
          return `I detected an overall error rate of **${stats.errorRate.toFixed(2)}%**. The most common error pattern is linked to \`${stats.clusters.find(c => c.errorCount > 0)?.template || 'N/A'}\` which occurred ${stats.clusters.find(c => c.errorCount > 0)?.errorCount || 0} times.`;
      }
      if (q.includes('latency') || q.includes('slow')) {
          return `The 95th percentile latency is **${stats.p95Latency.toFixed(0)}ms**. The slowest endpoint appears to be \`${stats.topEndpoints.sort((a,b) => b.avgLatency - a.avgLatency)[0]?.path}\`.`;
      }
      if (q.includes('summary') || q.includes('overview')) {
          return `Here's the summary:\n- **Traffic**: ${stats.requestsOverTime.length} data points processed.\n- **Health**: System is at ${stats.goldenSignals.errors > 1 ? 'High Risk' : 'Normal'} levels.\n- **Top Issue**: ${stats.clusters[0]?.template.substring(0, 50)}...`;
