                timestamp: parseDate(timestamp),
                originalTimestamp: timestamp,
                method: 'LOG',
                path: path,
                fullRequest: content,
                status,
                latency,
                upstreamLatency: 0,
                userAgent: '-',
                remoteIp: '-',
                referer: '-',
                isError: severity === 'ERROR',
                severity,
                bodyBytes: 0,
                rawLine: line,
                metadata: { stream }
            };
        }

        // 3. PostgreSQL Logs
        match = line.match(PG_REGEX);
        if (match) {
             const [, timestamp, tz, pid, user, level, message] = match;

             let latency = 0;
             const durMatch = message.match(/duration: ([\d.]+) ms/);
             if (durMatch) latency = parseFloat(durMatch[1]);

             const severity: LogSeverity = 
                ['ERROR', 'FATAL', 'PANIC'].includes(level) ? 'ERROR' :
                level === 'WARNING' ? 'WARN' : 'INFO';

             // Extract SQL verb and "table" hint
             // e.g. "statement: SELECT * FROM users"
             let method = 'SQL';
             let path = 'query';
             const stmtMatch = message.match(/statement: (\w+)(?:.*?FROM (\w+))?/i);
             if (stmtMatch) {
                 method = stmtMatch[1].toUpperCase();
                 if (stmtMatch[2]) path = stmtMatch[2];
                 else if (method === 'SELECT') path = 'unknown_table';
             }

             return {
                id: `log-pg-${i}`,
                timestamp: parseDate(timestamp),
                originalTimestamp: timestamp,
                method,
                path, 
                fullRequest: message,
                status: 0,
                latency,
                upstreamLatency: 0,
                userAgent: `Postgres ${pid}`,
                remoteIp: '-',
                referer: '-',
                isError: severity === 'ERROR',
                severity,
                bodyBytes: 0,
                rawLine: line,
                metadata: { pid, user, timezone: tz }
            };
        }

        // Generic Fallback
        return {
            id: `log-unk-${i}`,
            timestamp: new Date().toISOString(),
            originalTimestamp: '',
            method: 'MSG',
            path: 'raw_log',
            fullRequest: line.substring(0, 100),
            status: 0,
            latency: 0,
            upstreamLatency: 0,
            userAgent: '-',
            remoteIp: '-',
            referer: '-',
            isError: false,
            severity: 'INFO',
            bodyBytes: 0,
            rawLine: line,
            metadata: {}
        };
    }).filter(Boolean) as ProcessedLogEntry[];
};

export const parseLogs = (content: string): ProcessedLogEntry[] => {
  const lines = content.split(/\r?\n/).filter(line => line.trim() !== '');
  if (lines.length === 0) return [];

  // Heuristic: If first line looks like JSON
  if (lines[0].trim().startsWith('{')) {
      return parseJSONLines(lines);
  }

  // Fallback to TSV/CSV if header exists
  if (lines[0].includes('\t') || (lines[0].includes(',') && lines[0].includes('status'))) {
      return parseCSV(lines);
  }

  return parseRawText(lines);
};

const parseCSV = (lines: string[]): ProcessedLogEntry[] => {
    const firstLine = lines[0];
    const separator = firstLine.includes('\t') ? '\t' : ',';
    const headers = firstLine.split(separator).map(h => h.trim().replace(/^'|'$/g, ''));
    const findIdx = (keyParts: string[]) => headers.findIndex(h => keyParts.some(k => h.includes(k)));

    const idxStatus = findIdx(['jsonPayload.status', 'status']);
    const idxRequest = findIdx(['jsonPayload.request', 'request']);
    const idxReqTime = findIdx(['jsonPayload.request_time', 'request_time']);
    const idxUserAgent = findIdx(['jsonPayload.http_user_agent', 'http_user_agent']);
    const idxTimeLocal = findIdx(['jsonPayload.time_local', 'time_local']);

    return lines.slice(1).map((line, i) => {
        const cells = line.split(separator).map(c => c.trim().replace(/^"|"$/g, ''));
        if (cells.length < headers.length * 0.5) return null;

        const requestStr = cells[idxRequest] || '-';
        const { method, path } = normalizePath(requestStr);
        const status = parseInt(cells[idxStatus] || '0', 10);
        const latency = parseFloat(cells[idxReqTime] || '0');

        return {
            id: `log-csv-${i}`,
            timestamp: parseDate(cells[idxTimeLocal]),
            originalTimestamp: cells[idxTimeLocal] || '',
            method,
            path,
            fullRequest: requestStr,
            status: isNaN(status) ? 0 : status,
            latency: isNaN(latency) ? 0 : latency,
            upstreamLatency: 0,
            userAgent: cells[idxUserAgent] || '-',
            remoteIp: '-',
            referer: '-',
            isError: status >= 400,
            severity: determineSeverity(status, requestStr),
            bodyBytes: 0,
            rawLine: line,
            metadata: {}
        };
    }).filter(Boolean) as ProcessedLogEntry[];
};

export const aggregateStats = (logs: ProcessedLogEntry[]): AggregatedStats => {
  const totalRequests = logs.length;
  if (totalRequests === 0) {
    return {
      totalRequests: 0,
      avgLatency: 0,
      p50Latency: 0,
      p90Latency: 0,
      p95Latency: 0,
      p99Latency: 0,
      errorRate: 0,
      totalBytes: 0,
      requestsOverTime: [],
      statusDistribution: [],
      topEndpoints: [],
      methodDistribution: [],
      goldenSignals: { latency: 0, traffic: 0, errors: 0, saturation: 0 },
      clusters: []
    };
  }

  const latencies = logs.map(l => l.latency).sort((a, b) => a - b);
  const totalLatency = latencies.reduce((a, b) => a + b, 0);
  const totalBytes = logs.reduce((a, b) => a + (isNaN(b.bodyBytes) ? 0 : b.bodyBytes), 0);
  const errorCount = logs.filter(l => l.isError).length;

  const statusCounts: Record<string, number> = {};
  logs.forEach(l => {
    const cat = Math.floor(l.status / 100) + 'xx';
    statusCounts[cat] = (statusCounts[cat] || 0) + 1;
  });

  const statusColors: Record<string, string> = {
    '2xx': '#10b981', '3xx': '#3b82f6', '4xx': '#f59e0b', '5xx': '#ef4444', '0xx': '#94a3b8'
  };

  const statusDistribution = Object.entries(statusCounts).map(([name, value]) => ({
    name, value, fill: statusColors[name] || '#64748b',
  }));

  const endpointMap: Record<string, { count: number; totalLat: number; errors: number }> = {};
  logs.forEach(l => {
    const key = `${l.method} ${l.path}`;
    if (!endpointMap[key]) endpointMap[key] = { count: 0, totalLat: 0, errors: 0 };
    endpointMap[key].count++;
    endpointMap[key].totalLat += l.latency;
    if (l.isError) endpointMap[key].errors++;
  });

  const topEndpoints = Object.entries(endpointMap)
    .map(([path, data]) => ({
      path,
      count: data.count,
      avgLatency: data.totalLat / data.count,
      errorRate: (data.errors / data.count) * 100,
    }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 10);

  const timeMap: Record<string, { count: number; errors: number; totalLat: number }> = {};
  let minTime = Infinity;
  let maxTime = 0;

  logs.forEach(l => {
    const t = new Date(l.timestamp).getTime();
    if (t < minTime) minTime = t;
    if (t > maxTime) maxTime = t;

    const bucket = l.timestamp.substring(0, 16).replace('T', ' ');
    if (!timeMap[bucket]) timeMap[bucket] = { count: 0, errors: 0, totalLat: 0 };
    timeMap[bucket].count++;
    timeMap[bucket].totalLat += l.latency;
    if (l.isError) timeMap[bucket].errors++;
  });

  const requestsOverTime = Object.entries(timeMap)
    .map(([time, data]) => ({
      time,
      count: data.count,
      errorCount: data.errors,
      avgLatency: data.totalLat / data.count,
    }))
    .sort((a, b) => new Date(a.time).getTime() - new Date(b.time).getTime());

  const methodCounts: Record<string, number> = {};
  logs.forEach(l => { methodCounts[l.method] = (methodCounts[l.method] || 0) + 1; });
  const methodDistribution = Object.entries(methodCounts).map(([name, value]) => ({ name, value }));

  const durationSeconds = (maxTime - minTime) / 1000;
  const traffic = durationSeconds > 0 ? totalRequests / durationSeconds : totalRequests; // req/sec
  const p95 = calculatePercentile(latencies, 95);

  const clusterMap: Record<string, LogCluster> = {};
  logs.forEach(l => {
      const template = generateLogTemplate(l.fullRequest);
      const hash = template; 
      if (!clusterMap[hash]) {
          clusterMap[hash] = {
              id: Math.random().toString(36).substr(2, 9),
              template,
              sample: l.fullRequest,
              count: 0,
              errorCount: 0,
              avgLatency: 0,
              severity: l.severity
          };
      }
      const c = clusterMap[hash];
      c.count++;
      if (l.isError) c.errorCount++;
      c.avgLatency += l.latency;
      l.clusterId = c.id; 
  });

  const clusters = Object.values(clusterMap)
    .map(c => ({...c, avgLatency: c.avgLatency / c.count}))
    .sort((a, b) => b.count - a.count)
    .slice(0, 20); 

  return {
    totalRequests,
    avgLatency: totalLatency / totalRequests,
    p50Latency: calculatePercentile(latencies, 50),
    p90Latency: calculatePercentile(latencies, 90),
    p95Latency: p95,
    p99Latency: calculatePercentile(latencies, 99),
    errorRate: (errorCount / totalRequests) * 100,
    totalBytes,
    requestsOverTime,
    statusDistribution,
    topEndpoints,
    methodDistribution,
    goldenSignals: {
        latency: p95,
        traffic,
        errors: (errorCount / totalRequests) * 100,
        saturation: Math.min((traffic / 100) * 100, 100) 
    },
    clusters
  };
};

import React, { useState, useMemo } from 'react';
import { ProcessedLogEntry } from '../types';
import { Search, AlertTriangle, CheckCircle, Info, XCircle, Tag } from 'lucide-react';

interface Props {
  logs: ProcessedLogEntry[];
}

const LogExplorer: React.FC<Props> = ({ logs }) => {
  const [search, setSearch] = useState('');
  const [severityFilter, setSeverityFilter] = useState<string>('ALL');

  const filtered = useMemo(() => {
    return logs.filter(l => {
      if (severityFilter !== 'ALL' && l.severity !== severityFilter) return false;
      if (!search) return true;
      return l.rawLine.toLowerCase().includes(search.toLowerCase());
    });
  }, [logs, search, severityFilter]);

  return (
    <div className="flex flex-col h-[600px] bg-slate-900 border border-slate-700 rounded-xl overflow-hidden shadow-2xl">
      {/* Toolbar */}
      <div className="bg-slate-800 p-3 border-b border-slate-700 flex flex-wrap gap-4 items-center justify-between">
        <div className="flex items-center gap-2 bg-slate-900 border border-slate-700 rounded-lg px-3 py-1.5 w-full md:w-96 focus-within:border-blue-500 transition-colors">
          <Search size={14} className="text-slate-500" />
          <input 
            type="text" 
            placeholder="Regex search..." 
            className="bg-transparent border-none outline-none text-sm text-slate-200 w-full font-mono placeholder:text-slate-600"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        <div className="flex gap-1">
          {['ALL', 'INFO', 'WARN', 'ERROR', 'CRITICAL'].map(level => (
            <button
              key={level}
              onClick={() => setSeverityFilter(level)}
              className={`
                px-3 py-1 text-xs font-bold rounded-md transition-all
                ${severityFilter === level 
                  ? 'bg-slate-700 text-white shadow' 
                  : 'text-slate-500 hover:text-slate-300 hover:bg-slate-800'}
              `}
            >
              {level}
            </button>
          ))}
        </div>
      </div>

      {/* Log Window */}
      <div className="flex-1 overflow-auto bg-[#0a0f1e] p-2 font-mono text-xs md:text-sm">
        {filtered.slice(0, 500).map((log, i) => (
          <div key={log.id} className="group flex items-start gap-3 hover:bg-slate-800/30 p-1 rounded transition-colors border-l-2 border-transparent hover:border-slate-600">
            {/* Timestamp */}
            <span className="text-slate-500 shrink-0 select-none w-36">{log.timestamp.replace('T', ' ').slice(0, 19)}</span>

            {/* Severity Icon */}
            <span className="shrink-0 pt-0.5">
               {log.severity === 'INFO' && <Info size={14} className="text-blue-500/70" />}
               {log.severity === 'WARN' && <AlertTriangle size={14} className="text-amber-500/70" />}
               {log.severity === 'ERROR' && <XCircle size={14} className="text-red-500/70" />}
               {log.severity === 'CRITICAL' && <AlertTriangle size={14} className="text-purple-500" />}
            </span>

            {/* Content */}
            <div className="break-all text-slate-300 flex-1">
               {/* Highlight method if present */}
               <span className={`font-bold mr-2 ${
                   log.method === 'GET' ? 'text-blue-400' : 
                   log.method === 'POST' ? 'text-green-400' : 
                   log.method === 'DELETE' ? 'text-red-400' : 
                   log.method === 'SQL' ? 'text-purple-400' :
                   log.method === 'LOG' ? 'text-slate-400' : 'text-slate-400'
               }`}>
                   {log.method}
               </span>
               <span className="text-slate-400 mr-2">{log.path}</span>

               {/* Status */}
               {log.status > 0 && (
                   <span className={`px-1.5 rounded text-[10px] mr-2 ${
                       log.status >= 500 ? 'bg-red-500/20 text-red-300' :
                       log.status >= 400 ? 'bg-amber-500/20 text-amber-300' :
                       'bg-green-500/20 text-green-300'
                   }`}>
                       {log.status}
                   </span>
               )}

               <span className="opacity-80">{log.fullRequest.length > 200 ? log.fullRequest.substring(0, 200) + '...' : log.fullRequest}</span>

               {/* Metadata Tags */}
               {Object.keys(log.metadata || {}).length > 0 && (
                 <div className="flex gap-2 mt-1 flex-wrap opacity-60">
                   {Object.entries(log.metadata).map(([k, v]) => (
                     <span key={k} className="flex items-center gap-1 text-[10px] bg-slate-800 px-1.5 rounded text-slate-400 border border-slate-700">
                       <Tag size={10} />
                       {k}: {String(v)}
                     </span>
                   ))}
                 </div>
               )}
            </div>
          </div>
        ))}

        {filtered.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center text-slate-600">
            <Search size={48} className="mb-4 opacity-20" />
            <p>No logs match your filter.</p>
          </div>
        )}

        {filtered.length > 500 && (
          <div className="py-4 text-center text-slate-500 italic border-t border-slate-800/50 mt-4">
            Showing first 500 of {filtered.length} matches...
          </div>
        )}
      </div>
    </div>
  );
};

export default LogExplorer;

