const FileUpload: React.FC<FileUploadProps> = ({ onDataLoaded }) => {
  const [isDragging, setIsDragging] = useState(false);
  const [activeTab, setActiveTab] = useState<'upload' | 'paste'>('upload');
  const [textInput, setTextInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFile = async (file: File) => {
    setIsProcessing(true);
    try {
        let content = '';
        if (file.name.endsWith('.gz')) {
            const buffer = await file.arrayBuffer();
            const decompressed = gunzipSync(new Uint8Array(buffer));
            content = new TextDecoder().decode(decompressed);
        } else if (file.name.endsWith('.zip')) {
            const buffer = await file.arrayBuffer();
            const unzipped = unzipSync(new Uint8Array(buffer));
            // Combine all text-like files
            for (const path in unzipped) {
                 if (!path.endsWith('/') && !path.includes('__MACOSX')) {
                     content += new TextDecoder().decode(unzipped[path]) + '\n';
                 }
            }
        } else {
            content = await file.text();
        }
        onDataLoaded(content);
    } catch (e) {
        console.error("File processing error", e);
        alert('Failed to process file. Ensure it is a valid text, zip, or gz file.');
    } finally {
        setIsProcessing(false);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    const file = e.dataTransfer.files[0];
    if (file) {
      await processFile(file);
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      await processFile(file);
    }
  };

  const handlePasteSubmit = () => {
      if (textInput.trim()) {
          onDataLoaded(textInput);
      }
  };

  const loadSample = (type: string) => {
    onDataLoaded(SAMPLE_LOGS[type]);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-slate-900 to-black text-white flex flex-col items-center justify-center p-4">
      <div className="max-w-4xl w-full space-y-8">

        {/* Header */}
        <div className="text-center space-y-4">
            <h1 className="text-5xl md:text-7xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-cyan-400 via-blue-500 to-purple-600 pb-2">
                LogPulse Analytics
