import React, { useState, useRef, useEffect } from 'react';
import { Bot, Send, Sparkles, User } from 'lucide-react';
import { AggregatedStats } from '../types';
import { GoogleGenAI } from "@google/genai";

interface FilterContext {
  filterText: string;
  selectedMethods: string[];
  selectedStatusClasses: string[];
  minLatency: string;
  maxLatency: string;
  timeRange: string;
}

interface Props {
  stats: AggregatedStats;
  filters?: FilterContext;
}

interface Message {
  role: 'user' | 'assistant';
  content: string;
}

const AIInsights: React.FC<Props> = ({ stats, filters }) => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    { role: 'assistant', content: "I'm your LogPulse AI Assistant. I've analyzed the current log set. Ask me about error spikes, latency trends, or anomaly clusters." }
  ]);
  const [isProcessing, setIsProcessing] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
        scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg = input;
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setInput('');
    setIsProcessing(true);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        let filterContextStr = '';
        if (filters) {
            const methods = filters.selectedMethods.length > 0 ? filters.selectedMethods.join(', ') : 'All';
            const statuses = filters.selectedStatusClasses.length > 0 ? filters.selectedStatusClasses.join(', ') : 'All';
            const latency = `${filters.minLatency || '0'}ms - ${filters.maxLatency || '∞'}ms`;

            filterContextStr = `
        Active View Filters:
        - Time Range: ${filters.timeRange}
        - Search Query: "${filters.filterText || 'None'}"
        - Methods: ${methods}
        - Status Classes: ${statuses}
        - Latency Range: ${latency}
            `;
        }

        // Contextualize the logs for the AI
        const context = `
        ${filterContextStr}

        System Stats (Computed from Filtered View):
        - Total Requests: ${stats.totalRequests}
        - Error Rate: ${stats.errorRate.toFixed(2)}%
        - Avg Latency: ${stats.avgLatency.toFixed(2)}ms
        - P95 Latency: ${stats.p95Latency.toFixed(2)}ms
        - Traffic Trend: ${stats.requestsOverTime.length} data points
        - Top Endpoints: ${stats.topEndpoints.slice(0, 5).map(e => `${e.path} (${e.errorRate.toFixed(1)}% errors)`).join(', ')}
        - Significant Patterns: ${stats.clusters.slice(0, 3).map(c => c.template).join('\n')}
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Context:\n${context}\n\nUser Question: ${userMsg}\n\nAnswer as a SRE expert. If the user asks about filters, refer to the "Active View Filters" section provided.`,
        });

        const text = response.text || "I couldn't generate a response.";
        setMessages(prev => [...prev, { role: 'assistant', content: text }]);
    } catch (e) {
        console.error("AI Error", e);
        setMessages(prev => [...prev, { role: 'assistant', content: "I encountered an error processing your request. Please check the console or ensure the API key is valid." }]);
    } finally {
        setIsProcessing(false);
    }
  };

  return (
    <div className="h-[600px] flex flex-col bg-slate-900 border border-slate-700 rounded-xl overflow-hidden shadow-2xl relative">
      {/* Header */}
      <div className="bg-gradient-to-r from-indigo-900 to-slate-900 p-4 border-b border-indigo-500/30 flex justify-between items-center">
        <div className="flex items-center gap-3">
            <div className="p-2 bg-indigo-500/20 rounded-lg">
                <Sparkles size={20} className="text-indigo-400" />
            </div>
            <div>
                <h3 className="font-bold text-slate-100">AI Investigator</h3>
                <p className="text-xs text-indigo-300">Powered by Gemini 3 Flash</p>
            </div>
        </div>
      </div>

      {/* Chat Area */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 bg-[#0a0f1e]">
        {messages.map((msg, idx) => (
            <div key={idx} className={`flex gap-3 ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                {msg.role === 'assistant' && (
                    <div className="w-8 h-8 rounded-full bg-indigo-500/20 flex items-center justify-center shrink-0 border border-indigo-500/30">
                        <Bot size={16} className="text-indigo-400" />
                    </div>
                )}
                <div className={`
                    max-w-[80%] p-3 rounded-2xl text-sm leading-relaxed
                    ${msg.role === 'user' 
                        ? 'bg-blue-600 text-white rounded-br-none' 
                        : 'bg-slate-800 text-slate-200 border border-slate-700 rounded-bl-none'}
                `}>
                    <p className="whitespace-pre-wrap">{msg.content}</p>
                </div>
                {msg.role === 'user' && (
                    <div className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center shrink-0">
                        <User size={16} className="text-slate-300" />
                    </div>
                )}
            </div>
        ))}
        {isProcessing && (
             <div className="flex gap-3">
                 <div className="w-8 h-8 rounded-full bg-indigo-500/20 flex items-center justify-center shrink-0 border border-indigo-500/30">
                    <Bot size={16} className="text-indigo-400" />
                </div>
                <div className="bg-slate-800 p-3 rounded-2xl rounded-bl-none border border-slate-700 flex items-center gap-2">
                    <span className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce" style={{animationDelay: '0ms'}}></span>
                    <span className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce" style={{animationDelay: '150ms'}}></span>
                    <span className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce" style={{animationDelay: '300ms'}}></span>
                </div>
             </div>
        )}
      </div>

      {/* Input Area */}
      <div className="p-4 bg-slate-900 border-t border-slate-700">
        <div className="relative">
            <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Ask about errors, patterns, or latency..."
                className="w-full bg-slate-800 border border-slate-700 rounded-xl pl-4 pr-12 py-3 text-sm focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all shadow-inner text-slate-200"
            />
            <button 
                onClick={handleSend}
                disabled={!input.trim() || isProcessing}
                className="absolute right-2 top-2 p-1.5 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-700 rounded-lg text-white transition-colors"
            >
                <Send size={16} />
            </button>
        </div>
        <div className="flex gap-2 mt-2 justify-center">
            {['Explain the error spike', 'Show 5xx analysis', 'Summarize traffic'].map(suggestion => (
                <button 
                    key={suggestion}
                    onClick={() => setInput(suggestion)}
                    className="text-[10px] px-2 py-1 bg-slate-800 hover:bg-slate-700 border border-slate-700 rounded-md text-slate-400 transition-colors"
                >
                    {suggestion}
                </button>
            ))}
        </div>
      </div>
    </div>
  );
};

export default AIInsights;

import React, { useMemo, useState } from 'react';
import { ProcessedLogEntry } from '../types';
import { aggregateStats } from '../utils';
import GoldenSignals from './GoldenSignals';
import LogExplorer from './LogExplorer';
import AIInsights from './AIInsights';
import { TrafficChart, StatusDistribution, TopEndpointsChart } from './Charts';
import { LayoutDashboard, FileText, Layers, Sparkles, Filter, ArrowLeft, Search, X, Activity } from 'lucide-react';

interface DashboardProps {
  logs: ProcessedLogEntry[];
  onReset: () => void;
}

type Tab = 'OVERVIEW' | 'EXPLORER' | 'PATTERNS' | 'AI';
type TimeRange = 'ALL' | '15M' | '1H' | '6H' | '24H';

const Dashboard: React.FC<DashboardProps> = ({ logs, onReset }) => {
  const [activeTab, setActiveTab] = useState<Tab>('OVERVIEW');
  const [filterText, setFilterText] = useState('');
  const [selectedMethods, setSelectedMethods] = useState<string[]>([]);
  const [selectedStatusClasses, setSelectedStatusClasses] = useState<string[]>([]);
  const [minLatency, setMinLatency] = useState<string>('');
  const [maxLatency, setMaxLatency] = useState<string>('');
  const [timeRange, setTimeRange] = useState<TimeRange>('ALL');
  const [showFilters, setShowFilters] = useState(false);

  // Derive unique methods from logs for the filter options
  const availableMethods = useMemo(() => {
    const methods = new Set(logs.map(l => l.method));
    return Array.from(methods).sort();
  }, [logs]);

  // Determine the latest timestamp in the logs to act as "now" for relative time filtering
  const latestTimestamp = useMemo(() => {
    if (logs.length === 0) return 0;
    return logs.reduce((max, log) => {
        const t = new Date(log.timestamp).getTime();
        return t > max ? t : max;
    }, 0);
  }, [logs]);

  // Filter logs logic
  const filteredLogs = useMemo(() => {
    const minLat = minLatency === '' ? 0 : parseFloat(minLatency);
    const maxLat = maxLatency === '' ? Infinity : parseFloat(maxLatency);

    // Time range calculation
    let timeCutoff = 0;
    if (timeRange !== 'ALL' && latestTimestamp > 0) {
        const msMap: Record<string, number> = {
            '15M': 15 * 60 * 1000,
            '1H': 60 * 60 * 1000,
            '6H': 6 * 60 * 60 * 1000,
            '24H': 24 * 60 * 60 * 1000,
        };
        timeCutoff = latestTimestamp - (msMap[timeRange] || 0);
    }

    return logs.filter(log => {
      // 1. Text Search
      const matchesText = 
        filterText === '' ||
        log.path.toLowerCase().includes(filterText.toLowerCase()) || 
        log.method.toLowerCase().includes(filterText.toLowerCase());

      if (!matchesText) return false;

      // 2. Method Filter
      if (selectedMethods.length > 0 && !selectedMethods.includes(log.method)) {
          return false;
      }

      // 3. Status Class Filter
      if (selectedStatusClasses.length > 0) {
          const statusClass = Math.floor(log.status / 100) + 'xx';
          if (!selectedStatusClasses.includes(statusClass)) return false;
      }

      // 4. Latency Filter
      if (log.latency < minLat) return false;
      if (log.latency > maxLat) return false;

      // 5. Time Range
      if (timeCutoff > 0) {
          const logTime = new Date(log.timestamp).getTime();
          if (logTime < timeCutoff) return false;
      }

      return true;
    });
  }, [logs, filterText, selectedMethods, selectedStatusClasses, minLatency, maxLatency, timeRange, latestTimestamp]);

  const stats = useMemo(() => aggregateStats(filteredLogs), [filteredLogs]);

  const toggleMethod = (m: string) => {
      setSelectedMethods(prev => 
        prev.includes(m) ? prev.filter(x => x !== m) : [...prev, m]
      );
  };

  const toggleStatusClass = (c: string) => {
    setSelectedStatusClasses(prev => 
      prev.includes(c) ? prev.filter(x => x !== c) : [...prev, c]
    );
  };

  const clearFilters = () => {
      setFilterText('');
      setSelectedMethods([]);
      setSelectedStatusClasses([]);
      setMinLatency('');
      setMaxLatency('');
      setTimeRange('ALL');
  };

  const activeFilterCount = 
    (filterText ? 1 : 0) + 
    selectedMethods.length + 
    selectedStatusClasses.length + 
    (minLatency ? 1 : 0) + 
    (maxLatency ? 1 : 0) + 
    (timeRange !== 'ALL' ? 1 : 0);

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-200 pb-20 font-sans">
      {/* Navbar */}
      <nav className="border-b border-slate-800 bg-slate-900/95 backdrop-blur sticky top-0 z-50 shadow-lg">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="h-16 flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <button 
                        onClick={onReset}
                        className="p-2 hover:bg-slate-800 rounded-lg transition-colors text-slate-400 hover:text-white"
                        title="Upload new file"
                    >
                        <ArrowLeft size={20} />
                    </button>
                    <div className="flex flex-col">
                        <span className="font-bold text-lg bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-emerald-400">
                        LogPulse
                        </span>
                        <span className="text-[10px] uppercase tracking-widest text-slate-500 font-bold">
                            SRE Command Center
                        </span>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    {/* Tab Navigation */}
                    <div className="hidden md:flex items-center bg-slate-800/50 p-1 rounded-lg border border-slate-700/50 mr-4">
                        {[
                            { id: 'OVERVIEW', icon: LayoutDashboard, label: 'Overview' },
                            { id: 'EXPLORER', icon: FileText, label: 'Logs' },
                            { id: 'PATTERNS', icon: Layers, label: 'Patterns' },
                            { id: 'AI', icon: Sparkles, label: 'AI Insight' },
                        ].map(tab => (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id as Tab)}
                                className={`
                                    flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all
                                    ${activeTab === tab.id 
                                        ? 'bg-blue-600 text-white shadow-lg' 
                                        : 'text-slate-400 hover:text-slate-200 hover:bg-slate-700/50'}
                                `}
                            >
                                <tab.icon size={14} />
                                {tab.label}
                            </button>
                        ))}
                    </div>

                    <button 
                        onClick={() => setShowFilters(!showFilters)}
                        className={`
                            flex items-center gap-2 px-3 py-2 rounded-lg border transition-all text-sm font-medium
                            ${showFilters || activeFilterCount > 0
                                ? 'bg-blue-500/10 border-blue-500/50 text-blue-400' 
                                : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'}
                        `}
                    >
                        <Filter size={16} />
                        <span className="hidden sm:inline">Filters</span>
                        {activeFilterCount > 0 && (
                            <span className="bg-blue-500 text-white text-[10px] w-5 h-5 flex items-center justify-center rounded-full">
                                {activeFilterCount}
                            </span>
                        )}
                    </button>
                </div>
            </div>

            {/* Expandable Filter Bar */}
            {(showFilters || activeFilterCount > 0) && (
                <div className="py-4 border-t border-slate-800 space-y-4 animate-in slide-in-from-top-2 duration-200">
                    <div className="flex flex-wrap items-center gap-6">
                        {/* Time Range */}
                        <div className="space-y-1">
                            <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Time Range</label>
                            <div className="flex items-center bg-slate-800 rounded-lg p-1 border border-slate-700">
                                {['ALL', '24H', '6H', '1H', '15M'].map((range) => (
                                    <button
                                        key={range}
                                        onClick={() => setTimeRange(range as TimeRange)}
                                        className={`px-3 py-1 text-xs rounded-md transition-all ${
                                            timeRange === range 
                                            ? 'bg-slate-600 text-white shadow-sm font-medium' 
                                            : 'text-slate-400 hover:text-slate-200'
                                        }`}
                                    >
                                        {range}
                                    </button>
                                ))}
                            </div>
                        </div>

                         {/* Search Filter */}
                         <div className="space-y-1">
                            <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Search</label>
                            <div className="flex items-center bg-slate-800 rounded-lg px-2 py-1 border border-slate-700">
                                <Search size={14} className="text-slate-500 mr-2" />
                                <input 
                                    type="text"
                                    value={filterText}
                                    onChange={(e) => setFilterText(e.target.value)}
                                    placeholder="Method or Path..."
                                    className="bg-transparent border-none outline-none text-xs text-slate-200 w-32 md:w-48 placeholder:text-slate-600"
                                />
                            </div>
                         </div>

                         {/* Status Filter */}
                         <div className="space-y-1">
                            <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Status Class</label>
                            <div className="flex items-center gap-2">
                                {['2xx', '3xx', '4xx', '5xx'].map((cls) => {
                                    const isActive = selectedStatusClasses.includes(cls);
                                    let color = 'slate';
                                    if (cls === '2xx') color = 'emerald';
                                    if (cls === '3xx') color = 'blue';
                                    if (cls === '4xx') color = 'amber';
                                    if (cls === '5xx') color = 'red';

                                    return (
                                        <button
                                            key={cls}
                                            onClick={() => toggleStatusClass(cls)}
                                            className={`
                                                px-3 py-1.5 rounded-lg text-xs font-mono border transition-all
                                                ${isActive 
                                                    ? `bg-${color}-500/20 border-${color}-500 text-${color}-400` 
                                                    : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-500'}
                                            `}
                                        >
                                            {cls}
                                        </button>
                                    );
                                })}
                            </div>
                        </div>

                        {/* Latency Filter */}
                        <div className="space-y-1">
                             <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider">Latency (ms)</label>
                             <div className="flex items-center gap-2">
                                <input 
                                    type="number" 
                                    value={minLatency}
                                    onChange={(e) => setMinLatency(e.target.value)}
                                    placeholder="Min"
                                    className="bg-slate-800 border border-slate-700 rounded-lg px-2 py-1.5 text-sm w-20 focus:ring-1 focus:ring-blue-500 focus:border-blue-500 outline-none placeholder:text-slate-600"
                                />
                                <span className="text-slate-600">-</span>
                                <input 
                                    type="number" 
