             <div className="animate-in slide-in-from-bottom-2 duration-300">
                <LogExplorer logs={filteredLogs} />
             </div>
        )}

        {activeTab === 'PATTERNS' && (
            <div className="space-y-4 animate-in slide-in-from-bottom-2 duration-300">
                <div className="bg-slate-800/50 border border-slate-700 rounded-xl p-6">
                    <h3 className="text-lg font-bold text-slate-100 mb-4 flex items-center gap-2">
                        <Layers className="text-purple-400" size={20} />
                        Log Pattern Clustering
                    </h3>
                    <p className="text-slate-400 text-sm mb-6">
                        We've automatically grouped {filteredLogs.length} logs into {stats.clusters.length} unique patterns by removing dynamic variables (IDs, Timestamps, IPs).
                    </p>
                    <div className="space-y-3">
                        {stats.clusters.map(cluster => (
                            <div key={cluster.id} className="bg-slate-900 border border-slate-700 rounded-lg p-4 hover:border-slate-500 transition-colors group">
                                <div className="flex justify-between items-start mb-2">
                                    <div className="font-mono text-xs text-slate-300 break-all pr-4">
                                        {cluster.template}
                                    </div>
                                    <div className="flex flex-col items-end gap-1">
                                         <span className="text-xs font-bold text-slate-400">
                                            {cluster.count} occurrences
                                        </span>
                                        <div className="flex gap-2 text-[10px]">
                                             <span className={`${cluster.errorCount > 0 ? 'text-red-400' : 'text-slate-600'}`}>
                                                 {cluster.errorCount} Errors
                                             </span>
                                             <span className="text-slate-500">|</span>
                                             <span className="text-amber-400">
                                                 ~{cluster.avgLatency.toFixed(0)}ms avg
                                             </span>
                                        </div>
                                    </div>
                                </div>
                                <div className="text-[10px] text-slate-600 font-mono mt-2 bg-slate-950/50 p-2 rounded truncate group-hover:whitespace-normal group-hover:h-auto group-hover:overflow-visible transition-all">
                                    Sample: {cluster.sample}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {activeTab === 'ANOMALIES' && (
            <div className="space-y-4 animate-in slide-in-from-bottom-2 duration-300">
                <div className="bg-slate-800/50 border border-slate-700 rounded-xl p-6">
                     <h3 className="text-lg font-bold text-slate-100 mb-4 flex items-center gap-2">
                        <AlertTriangle className="text-amber-400" size={20} />
                        Statistical Anomalies
                    </h3>
                    <p className="text-slate-400 text-sm mb-6">
                        We detected {stats.anomalies.length} logs that deviate significantly from normal latency patterns (Z-Score > 3) or represent critical failures.
                    </p>
                    <div className="space-y-2">
                        {stats.anomalies.length === 0 ? (
                            <div className="p-8 text-center text-slate-500 bg-slate-900/50 rounded-lg border border-slate-800 border-dashed">
                                No significant anomalies detected in the current dataset.
                            </div>
                        ) : (
                            stats.anomalies.map(log => (
                                <div key={log.id} className="bg-slate-900 border border-red-900/50 rounded-lg p-3 flex gap-4 items-start hover:border-red-500/50 transition-colors">
                                    <div className="shrink-0 pt-1">
                                        <div className="bg-red-500/10 p-2 rounded text-red-400 font-bold text-xs flex flex-col items-center">
                                            <span>{log.latency.toFixed(0)}ms</span>
                                        </div>
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="flex justify-between">
                                            <span className="text-xs text-slate-500 font-mono">{log.timestamp}</span>
                                            {log.anomalyScore && (
                                                <span className="text-[10px] text-amber-500 bg-amber-500/10 px-2 rounded-full border border-amber-500/20">
                                                    +{log.anomalyScore.toFixed(1)}σ Deviation
                                                </span>
                                            )}
                                        </div>
                                        <div className="font-mono text-sm text-slate-200 truncate mt-1">
                                            {log.method} {log.path}
                                        </div>
                                        <div className="text-xs text-slate-500 mt-1 truncate">
                                            {log.fullRequest}
                                        </div>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            </div>
        )}

        {activeTab === 'AI' && (
             <div className="animate-in slide-in-from-bottom-2 duration-300">
                 <AIInsights 
                    stats={stats} 
                    filters={{
                        filterText,
                        selectedMethods,
                        selectedStatusClasses,
                        minLatency,
                        maxLatency,
                        timeRange
                    }}
                 />
             </div>
        )}

      </main>
    </div>
  );
};

