const FileUpload: React.FC<FileUploadProps> = ({ onDataLoaded }) => {
  const [isDragging, setIsDragging] = useState(false);
  const [activeTab, setActiveTab] = useState<'upload' | 'paste'>('upload');
  const [textInput, setTextInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const processFile = async (file: File) => {
    setIsProcessing(true);
    try {
        let content = '';
        if (file.name.endsWith('.gz')) {
            const buffer = await file.arrayBuffer();
            const decompressed = gunzipSync(new Uint8Array(buffer));
            content = new TextDecoder().decode(decompressed);
        } else if (file.name.endsWith('.zip')) {
            const buffer = await file.arrayBuffer();
            const unzipped = unzipSync(new Uint8Array(buffer));
            // Combine all text-like files
            for (const path in unzipped) {
                 if (!path.endsWith('/') && !path.includes('__MACOSX')) {
                     content += new TextDecoder().decode(unzipped[path]) + '\n';
                 }
            }
        } else {
            content = await file.text();
        }
        onDataLoaded(content);
    } catch (e) {
        console.error("File processing error", e);
        alert('Failed to process file. Ensure it is a valid text, zip, or gz file.');
    } finally {
        setIsProcessing(false);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    const file = e.dataTransfer.files[0];
    if (file) {
      await processFile(file);
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      await processFile(file);
    }
  };

  const handlePasteSubmit = () => {
      if (textInput.trim()) {
          onDataLoaded(textInput);
      }
  };

  const loadSample = (type: string) => {
    onDataLoaded(SAMPLE_LOGS[type]);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-slate-900 to-black text-white flex flex-col items-center justify-center p-4">
      <div className="max-w-4xl w-full space-y-8">

        {/* Header */}
        <div className="text-center space-y-4">
            <h1 className="text-5xl md:text-7xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-cyan-400 via-blue-500 to-purple-600 pb-2">
                LogPulse Analytics
            </h1>
            <p className="text-slate-400 text-lg md:text-xl font-light max-w-2xl mx-auto">
                The modern, privacy-first command center for SREs. Visualize latency, track errors, and cluster patterns instantly in your browser.
            </p>
        </div>

        {/* Tab Navigation */}
        <div className="flex justify-center">
            <div className="bg-slate-800/50 p-1 rounded-xl border border-slate-700/50 flex gap-1">
                <button 
                    onClick={() => setActiveTab('upload')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-medium transition-all ${
                        activeTab === 'upload' 
                        ? 'bg-blue-600 text-white shadow-lg' 
                        : 'text-slate-400 hover:text-white hover:bg-slate-700/50'
                    }`}
                >
                    <UploadCloud size={16} /> File Upload
                </button>
                <button 
                    onClick={() => setActiveTab('paste')}
                    className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-medium transition-all ${
                        activeTab === 'paste' 
                        ? 'bg-blue-600 text-white shadow-lg' 
                        : 'text-slate-400 hover:text-white hover:bg-slate-700/50'
                    }`}
                >
                    <Clipboard size={16} /> Paste Text
                </button>
            </div>
        </div>

        <div className="bg-slate-900/40 backdrop-blur-xl border border-slate-700/50 rounded-3xl p-8 shadow-2xl relative overflow-hidden">
            {isProcessing && (
                <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex flex-col items-center justify-center">
                    <Loader2 size={48} className="text-blue-500 animate-spin mb-4" />
                    <p className="text-lg font-medium text-blue-200">Processing Logs...</p>
                    <p className="text-sm text-slate-400">Decompressing and parsing data</p>
                </div>
            )}

            {/* Upload Tab */}
            {activeTab === 'upload' && (
                <div 
                    className={`
                        relative group rounded-2xl border-2 border-dashed transition-all duration-300 ease-out py-12 px-8 text-center cursor-pointer
                        ${isDragging 
                            ? 'border-cyan-400 bg-cyan-900/10 scale-[1.01] shadow-2xl shadow-cyan-500/20' 
                            : 'border-slate-700 hover:border-slate-500 hover:bg-slate-800/30'}
                    `}
                    onDragOver={handleDragOver}
                    onDragLeave={handleDragLeave}
                    onDrop={handleDrop}
                    onClick={() => fileInputRef.current?.click()}
                >
                    <input 
                        type="file" 
                        ref={fileInputRef} 
                        onChange={handleFileSelect} 
                        className="hidden" 
                        accept=".log,.txt,.json,.csv,.tsv,.gz,.zip"
                    />

                    <div className="flex flex-col items-center gap-6 pointer-events-none">
                        <div className={`
                            p-6 rounded-full bg-slate-800 shadow-xl transition-transform duration-300 group-hover:scale-110 group-hover:bg-slate-700
                        `}>
                            <UploadCloud size={48} className="text-cyan-400" />
                        </div>
                        <div className="space-y-2">
                            <h3 className="text-2xl font-semibold text-white">Drop your logs here</h3>
                            <p className="text-slate-400">Supports .log, .json, .csv, .zip, .gz</p>
                        </div>
                        <div className="flex gap-2 text-[10px] text-slate-500 font-mono uppercase tracking-wider">
                            <span className="bg-slate-800 px-2 py-1 rounded">Text</span>
                            <span className="bg-slate-800 px-2 py-1 rounded">GZIP</span>
                            <span className="bg-slate-800 px-2 py-1 rounded">ZIP</span>
                        </div>
                    </div>
                </div>
            )}

            {/* Paste Tab */}
            {activeTab === 'paste' && (
                <div className="space-y-4 h-[350px] flex flex-col">
                    <textarea 
                        className="w-full flex-1 bg-slate-950 border border-slate-700 rounded-xl p-4 text-sm font-mono text-slate-300 focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 resize-none placeholder:text-slate-600"
                        placeholder="Paste your raw logs here..."
                        value={textInput}
                        onChange={(e) => setTextInput(e.target.value)}
                    />
                    <div className="flex justify-end">
                        <button 
                            disabled={!textInput.trim()}
                            onClick={handlePasteSubmit}
                            className="bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white px-6 py-2 rounded-lg font-medium transition-colors shadow-lg shadow-blue-500/20"
                        >
                            Analyze Text
                        </button>
                    </div>
                </div>
            )}
        </div>

        {/* Sample Data Section */}
        <div className="space-y-6">
            <div className="flex items-center gap-3 text-slate-400 text-sm font-medium uppercase tracking-widest divider">
                <span className="h-px bg-slate-800 flex-1"></span>
                <span>Or try with Sample Data</span>
                <span className="h-px bg-slate-800 flex-1"></span>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
                {[
                    { name: 'GCP Load Balancer', icon: Globe, color: 'text-blue-400', desc: 'JSON Structure' },
                    { name: 'Nginx Access Logs', icon: Server, color: 'text-green-400', desc: 'CLF / Combined' },
                    { name: 'Application Logs (JSON)', icon: Code, color: 'text-purple-400', desc: 'Structured App' },
                    { name: 'AWS ALB Logs', icon: Cloud, color: 'text-orange-400', desc: 'ELB / ALB Format' },
                    { name: 'Kubernetes Pod Logs', icon: Database, color: 'text-cyan-400', desc: 'StdOut / StdErr' },
                    { name: 'PostgreSQL Logs', icon: Zap, color: 'text-yellow-400', desc: 'DB Queries' },
                ].map((sample) => (
                    <button
                        key={sample.name}
                        onClick={() => loadSample(sample.name)}
                        className="group bg-slate-800/40 hover:bg-slate-800 border border-slate-700/50 hover:border-slate-600 rounded-xl p-4 text-left transition-all hover:-translate-y-1 hover:shadow-xl"
                    >
                        <sample.icon className={`mb-3 ${sample.color}`} size={24} />
                        <div className="font-semibold text-sm text-slate-200 group-hover:text-white mb-1">
                            {sample.name.split(' ')[0]}
                        </div>
                        <div className="text-[10px] text-slate-500 font-mono">
                            {sample.desc}
                        </div>
                    </button>
                ))}
            </div>
        </div>

      </div>
    </div>
  );
};

