                    </div>
                </div>
            )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8 animate-fade-in">

        {/* GOLDEN SIGNALS - Always Visible at Top */}
