                            <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2">
                                <Activity className="w-5 h-5 text-blue-500 dark:text-blue-400" />
                                Traffic & Errors
                            </h3>
                        </div>
                        <TrafficChart data={stats} theme={settings.theme} />
                    </div>

                    <div className="space-y-6">
                         <div className="bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl p-6 backdrop-blur-sm shadow-sm dark:shadow-xl h-[50%]">
                            <div className="flex items-center justify-between mb-2">
                                <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">Status</h3>
                            </div>
                            <StatusDistribution data={stats} theme={settings.theme} />
                             <div className="mt-2 grid grid-cols-2 gap-2 text-xs">
                                <div className="flex items-center gap-2 text-slate-600 dark:text-slate-300">
                                    <span className="w-2 h-2 rounded-full bg-emerald-500"></span>
                                    <span>2xx</span>
                                </div>
                                <div className="flex items-center gap-2 text-slate-600 dark:text-slate-300">
                                    <span className="w-2 h-2 rounded-full bg-blue-500"></span>
                                    <span>3xx</span>
                                </div>
                                <div className="flex items-center gap-2 text-slate-600 dark:text-slate-300">
                                    <span className="w-2 h-2 rounded-full bg-amber-500"></span>
                                    <span>4xx</span>
                                </div>
                                <div className="flex items-center gap-2 text-slate-600 dark:text-slate-300">
                                    <span className="w-2 h-2 rounded-full bg-red-500"></span>
                                    <span>5xx</span>
                                </div>
                            </div>
                        </div>

                        <div className="bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl p-6 backdrop-blur-sm shadow-sm dark:shadow-xl h-[46%]">
                             <div className="flex items-center justify-between mb-2">
                                <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2">
                                     <BarChart2 size={16} className="text-blue-500 dark:text-blue-400" /> Latency
                                </h3>
                            </div>
                            <LatencyHistogram data={stats} theme={settings.theme} />
                        </div>
                    </div>
                </div>

                {/* Row 2: Heatmap & Slowest Endpoints */}
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                     <div className="bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl p-6 backdrop-blur-sm shadow-sm dark:shadow-xl flex flex-col">
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2">
                                <Zap className="w-5 h-5 text-yellow-500 dark:text-yellow-400" />
                                Hourly Intensity
                            </h3>
                        </div>
                        <HeatmapGrid data={stats} theme={settings.theme} />
                    </div>

                    <div className="lg:col-span-2 bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl p-6 backdrop-blur-sm shadow-sm dark:shadow-xl">
                        <div className="flex items-center justify-between mb-6">
                            <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">Slowest Endpoints</h3>
                        </div>
                        <TopEndpointsChart data={stats} theme={settings.theme} />
                    </div>
                </div>
            </div>
        )}

        {activeTab === 'EXPLORER' && (
             <div className="animate-in slide-in-from-bottom-2 duration-300">
                <LogExplorer logs={filteredLogs} />
             </div>
        )}

        {activeTab === 'PATTERNS' && (
            <div className="space-y-4 animate-in slide-in-from-bottom-2 duration-300">
                <div className="bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl p-6">
                    <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 mb-4 flex items-center gap-2">
                        <Layers className="text-purple-500 dark:text-purple-400" size={20} />
                        Log Pattern Clustering
                    </h3>
                    <p className="text-slate-600 dark:text-slate-400 text-sm mb-6">
                        We've automatically grouped {filteredLogs.length} logs into {stats.clusters.length} unique patterns by removing dynamic variables (IDs, Timestamps, IPs).
                    </p>
                    <div className="space-y-3">
                        {stats.clusters.map(cluster => (
                            <div key={cluster.id} className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg p-4 hover:border-slate-400 dark:hover:border-slate-500 transition-colors group">
                                <div className="flex justify-between items-start mb-2">
                                    <div className="font-mono text-xs text-slate-700 dark:text-slate-300 break-all pr-4">
                                        {cluster.template}
                                    </div>
                                    <div className="flex flex-col items-end gap-1">
                                         <span className="text-xs font-bold text-slate-500 dark:text-slate-400">
                                            {cluster.count} occurrences
                                        </span>
                                        <div className="flex gap-2 text-[10px]">
                                             <span className={`${cluster.errorCount > 0 ? 'text-red-500 dark:text-red-400' : 'text-slate-500 dark:text-slate-600'}`}>
                                                 {cluster.errorCount} Errors
                                             </span>
                                             <span className="text-slate-400">|</span>
                                             <span className="text-amber-600 dark:text-amber-400">
                                                 ~{cluster.avgLatency.toFixed(0)}ms avg
                                             </span>
                                        </div>
                                    </div>
                                </div>
                                <div className="text-[10px] text-slate-500 dark:text-slate-600 font-mono mt-2 bg-white dark:bg-slate-950/50 p-2 rounded truncate group-hover:whitespace-normal group-hover:h-auto group-hover:overflow-visible transition-all border border-slate-100 dark:border-slate-800">
                                    Sample: {cluster.sample}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {activeTab === 'ANOMALIES' && (
            <div className="space-y-4 animate-in slide-in-from-bottom-2 duration-300">
                <div className="bg-white dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl p-6">
                     <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 mb-4 flex items-center gap-2">
                        <AlertTriangle className="text-amber-500 dark:text-amber-400" size={20} />
                        Statistical Anomalies
                    </h3>
                    <p className="text-slate-600 dark:text-slate-400 text-sm mb-6">
                        We detected {stats.anomalies.length} logs that deviate significantly from normal latency patterns (Z-Score > 3) or represent critical failures.
                    </p>
                    <div className="space-y-2">
                        {stats.anomalies.length === 0 ? (
                            <div className="p-8 text-center text-slate-500 bg-slate-50 dark:bg-slate-900/50 rounded-lg border border-slate-200 dark:border-slate-800 border-dashed">
                                No significant anomalies detected in the current dataset.
                            </div>
                        ) : (
                            stats.anomalies.map(log => (
                                <div key={log.id} className="bg-slate-50 dark:bg-slate-900 border border-red-200 dark:border-red-900/50 rounded-lg p-3 flex gap-4 items-start hover:border-red-400 dark:hover:border-red-500/50 transition-colors">
                                    <div className="shrink-0 pt-1">
                                        <div className="bg-red-500/10 p-2 rounded text-red-600 dark:text-red-400 font-bold text-xs flex flex-col items-center">
                                            <span>{log.latency.toFixed(0)}ms</span>
                                        </div>
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="flex justify-between">
                                            <span className="text-xs text-slate-500 font-mono">{log.timestamp}</span>
                                            {log.anomalyScore && (
                                                <span className="text-[10px] text-amber-600 dark:text-amber-500 bg-amber-100 dark:bg-amber-500/10 px-2 rounded-full border border-amber-200 dark:border-amber-500/20">
                                                    +{log.anomalyScore.toFixed(1)}σ Deviation
                                                </span>
                                            )}
                                        </div>
                                        <div className="font-mono text-sm text-slate-800 dark:text-slate-200 truncate mt-1">
                                            {log.method} {log.path}
                                        </div>
                                        <div className="text-xs text-slate-500 mt-1 truncate">
                                            {log.fullRequest}
                                        </div>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            </div>
        )}

        {activeTab === 'AI' && (
             <div className="animate-in slide-in-from-bottom-2 duration-300">
                 <AIInsights 
                    stats={stats} 
                    settings={settings}
                    filters={{
                        filterText,
                        selectedMethods,
                        selectedStatusClasses,
                        minLatency,
                        maxLatency,
                        timeRange
                    }}
                 />
             </div>
        )}

      </main>
    </div>
  );
};

export default Dashboard;

import React from 'react';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  Legend,
  ComposedChart,
  Line
} from 'recharts';
import { AggregatedStats } from '../types';

interface ChartsProps {
  data: AggregatedStats;
  theme: 'light' | 'dark';
}

const CustomTooltip = ({ active, payload, label, theme }: any) => {
  if (active && payload && payload.length) {
    const bgClass = theme === 'dark' ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-200';
    const textClass = theme === 'dark' ? 'text-slate-200' : 'text-slate-800';
    const subTextClass = theme === 'dark' ? 'text-slate-400' : 'text-slate-500';

    return (
      <div className={`${bgClass} border p-3 rounded shadow-xl z-50`}>
        <p className={`${subTextClass} text-sm mb-2 font-bold border-b ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'} pb-1`}>{label}</p>
        {payload.map((entry: any, index: number) => (
          <div key={index} className="flex items-center gap-2 text-sm">
            <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color || entry.fill }} />
            <span className={`${subTextClass} capitalize`}>{entry.name}:</span>
            <span className={`${textClass} font-mono`}>
                {typeof entry.value === 'number' && (entry.name.includes('Latency') || entry.name.includes('ms'))
                    ? entry.value.toFixed(2) + 'ms' 
                    : entry.value}
            </span>
          </div>
        ))}
      </div>
    );
  }
  return null;
};

export const TrafficChart: React.FC<ChartsProps> = ({ data, theme }) => {
  const gridColor = theme === 'dark' ? '#334155' : '#e2e8f0';
  const axisColor = theme === 'dark' ? '#94a3b8' : '#64748b';

  return (
    <div className="w-full h-[350px]">
      <ResponsiveContainer width="100%" height="100%">
        <ComposedChart data={data.requestsOverTime}>
          <defs>
            <linearGradient id="colorCount" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3} />
              <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
            </linearGradient>
            <linearGradient id="colorError" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="#ef4444" stopOpacity={0.3} />
              <stop offset="95%" stopColor="#ef4444" stopOpacity={0} />
            </linearGradient>
          </defs>
          <CartesianGrid strokeDasharray="3 3" stroke={gridColor} vertical={false} />
          <XAxis 
            dataKey="time" 
            stroke={axisColor}
            tickFormatter={(str) => {
              if (typeof str === 'string' && str.includes(' ')) {
                return str.split(' ')[1];
              }
              return str;
            }}
            tick={{fontSize: 12}}
            minTickGap={30}
          />
          <YAxis yAxisId="left" stroke={axisColor} tick={{fontSize: 12}} />
          <YAxis yAxisId="right" orientation="right" stroke="#10b981" unit="ms" tick={{fontSize: 12}} />
          <Tooltip content={<CustomTooltip theme={theme} />} />
          <Legend />
          <Area
            yAxisId="left"
            type="monotone"
            dataKey="count"
            name="Requests"
            stroke="#3b82f6"
            fillOpacity={1}
            fill="url(#colorCount)"
            strokeWidth={2}
          />
           <Area
            yAxisId="left"
            type="monotone"
            dataKey="errorCount"
            name="Errors"
            stroke="#ef4444"
            fillOpacity={1}
            fill="url(#colorError)"
            strokeWidth={2}
          />
          <Line
            yAxisId="right"
            type="monotone"
            dataKey="avgLatency"
            name="Avg Latency"
            stroke="#10b981"
            dot={false}
            strokeWidth={2}
          />
        </ComposedChart>
      </ResponsiveContainer>
    </div>
  );
};

export const StatusDistribution: React.FC<ChartsProps> = ({ data, theme }) => {
  return (
    <div className="w-full h-[250px]">
      <ResponsiveContainer width="100%" height="100%">
        <PieChart>
          <Pie
            data={data.statusDistribution}
            cx="50%"
            cy="50%"
            innerRadius={60}
            outerRadius={80}
            paddingAngle={5}
            dataKey="value"
          >
            {data.statusDistribution.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={entry.fill} stroke="rgba(0,0,0,0)" />
            ))}
          </Pie>
          <Tooltip content={<CustomTooltip theme={theme} />} />
          <Legend verticalAlign="bottom" height={36} iconType="circle" />
        </PieChart>
      </ResponsiveContainer>
    </div>
  );
};

export const TopEndpointsChart: React.FC<ChartsProps> = ({ data, theme }) => {
  const chartData = data.topEndpoints.slice(0, 5).map(e => ({
      ...e,
      shortPath: e.path.length > 30 ? '...' + e.path.slice(-30) : e.path
  }));
  const gridColor = theme === 'dark' ? '#334155' : '#e2e8f0';
  const axisColor = theme === 'dark' ? '#94a3b8' : '#64748b';

  return (
    <div className="w-full h-[300px]">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart layout="vertical" data={chartData} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
          <CartesianGrid strokeDasharray="3 3" stroke={gridColor} horizontal={false} />
          <XAxis type="number" stroke={axisColor} />
          <YAxis 
            type="category" 
            dataKey="shortPath" 
            stroke={axisColor} 
            width={150} 
            tick={{fontSize: 11}}
          />
          <Tooltip content={<CustomTooltip theme={theme} />} cursor={{fill: theme === 'dark' ? '#1e293b' : '#f1f5f9'}} />
          <Legend />
          <Bar dataKey="count" name="Volume" fill="#8b5cf6" radius={[0, 4, 4, 0]} barSize={20} />
          <Bar dataKey="avgLatency" name="Latency (ms)" fill="#f59e0b" radius={[0, 4, 4, 0]} barSize={20} />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

export const LatencyHistogram: React.FC<ChartsProps> = ({ data, theme }) => {
  const gridColor = theme === 'dark' ? '#334155' : '#e2e8f0';
  const axisColor = theme === 'dark' ? '#94a3b8' : '#64748b';

  return (
    <div className="w-full h-[250px]">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart data={data.latencyHistogram} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke={gridColor} vertical={false} />
          <XAxis dataKey="range" stroke={axisColor} tick={{fontSize: 10}} interval={2} />
          <YAxis stroke={axisColor} tick={{fontSize: 10}} />
          <Tooltip content={<CustomTooltip theme={theme} />} cursor={{fill: theme === 'dark' ? '#1e293b' : '#f1f5f9'}} />
          <Bar dataKey="count" name="Request Count" fill="#3b82f6" radius={[2, 2, 0, 0]} />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

export const HeatmapGrid: React.FC<ChartsProps> = ({ data, theme }) => {
  const maxCount = Math.max(...data.trafficHeatmap.map(d => d.count)) || 1;

  return (
    <div className="w-full h-full flex flex-col justify-between">
       <div className="flex justify-between items-end h-[200px] gap-1">
           {data.trafficHeatmap.map((d) => {
               const intensity = d.count / maxCount;
               const hasErrors = d.errorRate > 0.05;
               const bgClass = hasErrors ? 'bg-red-500' : 'bg-cyan-500';
               const opacity = Math.max(0.2, intensity);

               return (
                   <div key={d.hour} className="flex-1 flex flex-col items-center group relative">
                       {/* Tooltip on hover */}
                       <div className={`absolute bottom-full mb-2 hidden group-hover:block z-20 ${theme === 'dark' ? 'bg-slate-900 text-slate-200 border-slate-700' : 'bg-white text-slate-800 border-slate-200'} text-xs p-2 rounded border whitespace-nowrap shadow-xl`}>
                           <div className="font-bold">{d.hour}:00 - {d.hour}:59</div>
                           <div>Requests: {d.count}</div>
                           <div className={d.errorRate > 0 ? 'text-red-400' : (theme === 'dark' ? 'text-slate-400' : 'text-slate-500')}>
                               Error Rate: {(d.errorRate * 100).toFixed(1)}%
                           </div>
                       </div>

                       {/* Bar */}
                       <div 
                         className={`w-full rounded-t-sm transition-all hover:brightness-125 ${bgClass}`}
                         style={{ 
                             height: `${Math.max(5, intensity * 100)}%`,
                             opacity: opacity
                         }}
                       />
                   </div>
               )
           })}
       </div>
       <div className={`flex justify-between mt-2 text-[10px] ${theme === 'dark' ? 'text-slate-500 border-slate-700' : 'text-slate-400 border-slate-200'} border-t pt-1`}>
           {data.trafficHeatmap.filter((_, i) => i % 3 === 0).map(d => (
               <span key={d.hour}>{d.hour}:00</span>
           ))}
       </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Bot, Send, Sparkles, User, Settings2 } from 'lucide-react';
import { AggregatedStats, AppSettings } from '../types';
import { GoogleGenAI } from "@google/genai";
import ReactMarkdown from 'react-markdown';

interface FilterContext {
  filterText: string;
  selectedMethods: string[];
  selectedStatusClasses: string[];
  minLatency: string;
  maxLatency: string;
  timeRange: string;
}

interface Props {
  stats: AggregatedStats;
  filters?: FilterContext;
  settings: AppSettings;
}

interface Message {
  role: 'user' | 'assistant';
  content: string;
}

const AIInsights: React.FC<Props> = ({ stats, filters, settings }) => {
  const [input, setInput] = useState('');

  const [messages, setMessages] = useState<Message[]>(() => [{
      role: 'assistant',
      content: `I've analyzed the ${stats.totalRequests} logs in your current view.

**Quick Summary:**
• **Error Rate:** ${stats.errorRate.toFixed(2)}%
• **Avg Latency:** ${stats.avgLatency.toFixed(0)}ms
• **P95 Latency:** ${stats.p95Latency.toFixed(0)}ms
${stats.anomalies.length > 0 ? `• **Anomalies:** ${stats.anomalies.length} outliers detected` : ''}

Using Provider: **${settings.aiProvider === 'gemini' ? 'Google Gemini' : `Ollama (${settings.ollamaModel})`}**
`
  }]);

  const [isProcessing, setIsProcessing] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const isFirstRender = useRef(true);

  // Auto-scroll
  useEffect(() => {
    if (scrollRef.current) {
        scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  // Update notification on filter change
  useEffect(() => {
      if (isFirstRender.current) {
          isFirstRender.current = false;
          return;
      }
      const timer = setTimeout(() => {
          setMessages(prev => [
              ...prev,
              {
                  role: 'assistant',
                  content: `🔄 **View Updated**
New context: ${stats.totalRequests} requests, ${stats.errorRate.toFixed(2)}% errors, ${stats.avgLatency.toFixed(0)}ms latency.`
              }
          ]);
      }, 800);
      return () => clearTimeout(timer);
  }, [stats]);

  const generateWithGemini = async (prompt: string, context: string) => {
    const key = settings.geminiKey || process.env.API_KEY;
    if (!key) throw new Error("No Gemini API Key found in settings or environment.");

    const ai = new GoogleGenAI({ apiKey: key });
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Context:\n${context}\n\nUser Question: ${prompt}\n\nAnswer as a SRE expert.`,
    });
    return response.text || "No text generated.";
  };

  const generateWithOllama = async (prompt: string, context: string) => {
      const payload = {
          model: settings.ollamaModel,
          prompt: `You are an SRE expert analyzing server logs.

          CONTEXT DATA:
          ${context}

          USER QUESTION:
          ${prompt}

          ANSWER (Markdown):`,
          stream: false
      };

      try {
          const res = await fetch(`${settings.ollamaUrl}/api/generate`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(payload)
          });

          if (!res.ok) throw new Error(`Ollama Error: ${res.status} ${res.statusText}`);
          const data = await res.json();
          return data.response;
      } catch (e: any) {
          throw new Error(`Failed to connect to Ollama at ${settings.ollamaUrl}. Ensure it's running with 'ollama serve' and CORS is allowed (OLLAMA_ORIGINS="*"). Details: ${e.message}`);
      }
  };

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg = input;
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setInput('');
    setIsProcessing(true);

    try {
        let filterContextStr = '';
        if (filters) {
            const methods = filters.selectedMethods.length > 0 ? filters.selectedMethods.join(', ') : 'All';
            const statuses = filters.selectedStatusClasses.length > 0 ? filters.selectedStatusClasses.join(', ') : 'All';
            const latency = `${filters.minLatency || '0'}ms - ${filters.maxLatency || '∞'}ms`;

            filterContextStr = `
        Active View Filters:
        - Time Range: ${filters.timeRange}
        - Search Query: "${filters.filterText || 'None'}"
        - Methods: ${methods}
        - Status Classes: ${statuses}
        - Latency Range: ${latency}
            `;
        }

        const context = `
        ${filterContextStr}
        System Stats (Computed from Filtered View):
        - Total Requests: ${stats.totalRequests}
        - Error Rate: ${stats.errorRate.toFixed(2)}%
        - Avg Latency: ${stats.avgLatency.toFixed(2)}ms
        - P95 Latency: ${stats.p95Latency.toFixed(2)}ms
        - Top Endpoints: ${stats.topEndpoints.slice(0, 5).map(e => `${e.path} (${e.errorRate.toFixed(1)}% errors)`).join(', ')}
        - Significant Patterns: ${stats.clusters.slice(0, 3).map(c => c.template).join('\n')}
        `;

        let text = '';
        if (settings.aiProvider === 'ollama') {
            text = await generateWithOllama(userMsg, context);
        } else {
            text = await generateWithGemini(userMsg, context);
        }

        setMessages(prev => [...prev, { role: 'assistant', content: text }]);
    } catch (e: any) {
        console.error("AI Error", e);
        setMessages(prev => [...prev, { role: 'assistant', content: `Error: ${e.message}` }]);
    } finally {
        setIsProcessing(false);
    }
  };

  return (
    <div className="h-[600px] flex flex-col bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl overflow-hidden shadow-xl relative transition-colors duration-300">
      {/* Header */}
      <div className="bg-slate-50 dark:bg-gradient-to-r dark:from-indigo-900 dark:to-slate-900 p-4 border-b border-slate-200 dark:border-indigo-500/30 flex justify-between items-center">
        <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-100 dark:bg-indigo-500/20 rounded-lg">
                <Sparkles size={20} className="text-blue-600 dark:text-indigo-400" />
            </div>
            <div>
                <h3 className="font-bold text-slate-800 dark:text-slate-100">AI Investigator</h3>
                <p className="text-xs text-slate-500 dark:text-indigo-300 flex items-center gap-1">
                    Via {settings.aiProvider === 'ollama' ? 'Ollama' : 'Gemini'}
                </p>
            </div>
        </div>
      </div>

      {/* Chat Area */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50 dark:bg-[#0a0f1e]">
        {messages.map((msg, idx) => (
            <div key={idx} className={`flex gap-3 ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                {msg.role === 'assistant' && (
                    <div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-indigo-500/20 flex items-center justify-center shrink-0 border border-blue-200 dark:border-indigo-500/30">
                        <Bot size={16} className="text-blue-600 dark:text-indigo-400" />
                    </div>
                )}
                <div className={`
                    max-w-[85%] p-3 rounded-2xl text-sm leading-relaxed shadow-sm
                    ${msg.role === 'user' 
                        ? 'bg-blue-600 text-white rounded-br-none' 
                        : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-200 border border-slate-200 dark:border-slate-700 rounded-bl-none'}
                `}>
                    <ReactMarkdown 
                        components={{
                            p: ({node, ...props}) => <p className="mb-2 last:mb-0 whitespace-pre-wrap" {...props} />,
                            strong: ({node, ...props}) => <span className={`font-bold ${msg.role === 'user' ? 'text-white' : 'text-slate-900 dark:text-white'}`} {...props} />,
                            ul: ({node, ...props}) => <ul className="list-disc pl-4 mb-2 space-y-1" {...props} />,
                            ol: ({node, ...props}) => <ol className="list-decimal pl-4 mb-2 space-y-1" {...props} />,
                            li: ({node, ...props}) => <li className="pl-1" {...props} />,
                            a: ({node, ...props}) => <a className="text-blue-300 hover:underline" target="_blank" rel="noopener noreferrer" {...props} />,
                            code: ({node, className, children, ...props}: any) => {
                                return (
                                    <code className="bg-slate-100 dark:bg-slate-950 px-1 py-0.5 rounded font-mono text-xs border border-slate-200 dark:border-slate-700/50" {...props}>
                                        {children}
                                    </code>
                                )
                            },
                            pre: ({node, children, ...props}) => (
                                <pre className="bg-slate-100 dark:bg-slate-950 p-3 rounded-lg overflow-x-auto my-2 border border-slate-200 dark:border-slate-700/50" {...props}>
                                    {children}
                                </pre>
                            )
                        }}
                    >
                        {msg.content}
                    </ReactMarkdown>
                </div>
                {msg.role === 'user' && (
                    <div className="w-8 h-8 rounded-full bg-slate-300 dark:bg-slate-700 flex items-center justify-center shrink-0">
                        <User size={16} className="text-slate-600 dark:text-slate-300" />
                    </div>
                )}
            </div>
        ))}
        {isProcessing && (
             <div className="flex gap-3">
                 <div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-indigo-500/20 flex items-center justify-center shrink-0 border border-blue-200 dark:border-indigo-500/30">
                    <Bot size={16} className="text-blue-600 dark:text-indigo-400" />
                </div>
                <div className="bg-white dark:bg-slate-800 p-3 rounded-2xl rounded-bl-none border border-slate-200 dark:border-slate-700 flex items-center gap-2">
                    <span className="w-2 h-2 bg-blue-400 dark:bg-indigo-400 rounded-full animate-bounce" style={{animationDelay: '0ms'}}></span>
                    <span className="w-2 h-2 bg-blue-400 dark:bg-indigo-400 rounded-full animate-bounce" style={{animationDelay: '150ms'}}></span>
                    <span className="w-2 h-2 bg-blue-400 dark:bg-indigo-400 rounded-full animate-bounce" style={{animationDelay: '300ms'}}></span>
                </div>
             </div>
        )}
      </div>

      {/* Input Area */}
      <div className="p-4 bg-white dark:bg-slate-900 border-t border-slate-200 dark:border-slate-700">
        <div className="relative">
            <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder={`Ask ${settings.aiProvider === 'ollama' ? 'Llama' : 'Gemini'} about errors, patterns...`}
                className="w-full bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl pl-4 pr-12 py-3 text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition-all shadow-inner text-slate-800 dark:text-slate-200"
            />
            <button 
                onClick={handleSend}
                disabled={!input.trim() || isProcessing}
                className="absolute right-2 top-2 p-1.5 bg-blue-600 hover:bg-blue-500 disabled:bg-slate-300 dark:disabled:bg-slate-700 rounded-lg text-white transition-colors"
            >
                <Send size={16} />
            </button>
        </div>
        <div className="flex gap-2 mt-2 justify-center">
            {['Explain the error spike', 'Show 5xx analysis', 'Summarize traffic'].map(suggestion => (
                <button 
                    key={suggestion}
                    onClick={() => setInput(suggestion)}
                    className="text-[10px] px-2 py-1 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 border border-slate-200 dark:border-slate-700 rounded-md text-slate-600 dark:text-slate-400 transition-colors"
                >
                    {suggestion}
                </button>
            ))}
        </div>
      </div>
    </div>
  );
};

export default AIInsights;

